async function openPerms(id){const{data:p}=await sb.from("profiles").select(PCOLS).eq("id",id).single();C.pp=p;
const back=C.pb=="set"?"V.set()":"V.team()",ck=k=>`<input type="checkbox" id="p_${k}" ${can(k,p)?"checked":""} onchange="permPrev(this)" style="width:22px;height:22px;margin:0">`;
put(`<button class="btn g s" style="margin-top:12px" onclick="${back}">‹ رجوع</button><h1>شاشة ${esc(p.full_name)}</h1><p class="m">${RL[p.role]||""} · اللي تقفله مش هيظهر للموظف ولا هيقدر يوصله حتى من برّه التطبيق.</p><div class="pv"><div class="pv-h">كده هتظهر شاشته</div><div class="pv-nav" id="pv_nav"></div><div class="pv-me" id="pv_me"></div></div>`+PSC.map(g=>`<div class="pcard" id="pc_${g[0]}">${g[2]?`<label class="prow main"><span><b>${g[1]}</b><span class="m" style="display:block">${g[3]}</span></span>${ck(g[2])}</label>`:`<div class="prow main"><span><b>${g[1]}</b><span class="m" style="display:block">${g[3]}</span></span></div>`}${g[4].map(x=>`<label class="prow sub"><span>${x[1]}</span>${ck(x[0])}</label>`).join("")}</div>`).join("")+`<div class="chips" style="margin-top:12px"><button class="btn" onclick="savePerms()">حفظ الصلاحيات</button><button class="btn g" onclick="resetPerms()">رجوع للافتراضي</button></div>`);permPrev("init")}
function permPrev(el){PSC.forEach(g=>{if(!g[2])return;const m=$("p_"+g[2]);if(!m)return;g[4].forEach(x=>{const c=$("p_"+x[0]);if(!c)return;if((el===m||el==="init")&&!m.checked&&!c.disabled){c.dataset.prev=c.checked;c.checked=false}else if(el===m&&m.checked&&c.dataset.prev!==undefined){c.checked=c.dataset.prev=="true"}c.disabled=!m.checked})});
const st={};PERMS.forEach(x=>{if(x[0]!="ط"){const e=$("p_"+x[0]);if(e)st[x[0]]=e.checked}});const T=staffTabs({role:C.pp.role,perms:st}),hasMe=T.some(x=>x[0]=="me");
$("pv_nav").innerHTML=T.length?T.map(x=>`<div class="pv-t">${ic(x[0])}<span>${x[1]}</span></div>`).join(""):`<div class="m" style="padding:8px">مفيش أي شاشة هتظهر للموظف</div>`;
$("pv_me").innerHTML=hasMe?`<div class="m">جوه "شاشتي":</div><div class="chips">${[["use_attendance","حضور"],["view_own_schedule","جدول"],["view_own_sales","مبيعات"],["view_own_commission","عمولة"],["view_own_finance","مالية"],["view_own_reviews","تقييمات"]].map(x=>`<span class="tag ${st[x[0]]?"":"off"}">${x[1]}</span>`).join("")}</div>`:"";
PSC.forEach(g=>{const e=$("pc_"+g[0]);if(e)e.classList.toggle("off",g[2]?!st[g[2]]:!hasMe)})}
async function savePerms(){const o={};PERMS.forEach(x=>{if(x[0]!="ط")o[x[0]]=$("p_"+x[0]).checked});const{error}=await sb.from("profiles").update({perms:o}).eq("id",C.pp.id);error?toast(error.message):toast("تم حفظ الصلاحيات")}
