V.appts=async()=>{const t=new Date().toLocaleDateString("en-CA");
if(+C.cfg.no_show_after_minutes>0){try{await sb.rpc("run_no_show_sweep")}catch(e){}}
const{data}=await sb.from("appointments").select("id,day,period,ticket_no,status,called_at,eta,finished_at,customer_id,barber_id,customers(name),profiles(full_name),appointment_services(service_id,services(name))").gte("day",t).not("status","in","(cancelled,done)").order("day").order("ticket_no");
C.A=(data||[]).filter(a=>a.status!="no_show");put(`<h1>الدور</h1><button class="btn s" onclick="admForm()">+ حجز إداري</button><div id="adm"></div>`+(C.A.length?C.A.map(a=>`<div class="row"><div><b>#${a.ticket_no}</b> · ${esc(a.customers?.name)}<div class="m">${a.day} · ${PLB[a.period]} · ${a.appointment_services.map(x=>esc(x.services.name)).join(" + ")} · ${esc(a.profiles?.full_name||"-")}</div></div><div style="text-align:left"><span class="tag">${a.finished_at?"خلص":a.called_at&&a.status=="upcoming"?"مستدعى"+(a.eta=="on_way"?" (في الطريق)":""):ST[a.status]}</span><br>${a.status=="upcoming"&&!a.called_at?`<button class="btn s" onclick="tk('call_ticket',${a.id})">استدعاء</button> `:""}${a.status=="upcoming"||a.status=="checked_in"?`<button class="btn s g" onclick="setS(${a.id},'in_service')">ابدأ</button> `:""}${a.status=="in_service"?`<button class="btn s" onclick="payAppt(${a.id})">دفع</button> `:""}${(a.status=="upcoming"||a.status=="checked_in")&&a.called_at?`<button class="btn s g" onclick="noShow(${a.id})">لم يحضر</button> `:""}${a.status!="in_service"?`<button class="btn s g" onclick="setS(${a.id},'cancelled')">إلغاء</button>`:""}${me.role=="owner"?` <button class="btn s g" style="color:var(--red)" onclick="delAppt('${a.id}')">حذف</button>`:""}</div></div>`).join(""):`<p class="m">مفيش دور محجوز.</p>`));clearInterval(C.poll);C.poll=setInterval(()=>{if(tab=="appts"&&!($("adm")&&$("adm").innerHTML)){$("app").classList.add("still");V.appts()}},30000)};
