function qa(t,f,id){go(t);let n=0;const w=setInterval(()=>{if($(id)||++n>40){clearInterval(w);if($(id))window[f]()}},100)}
async function homeCall(id){const{error}=await sb.rpc("call_ticket",{p_id:id});error?toast(error.message):(toast("تم الاستدعاء ✓"),go("home"))}
V.home=async()=>{const t=new Date().toLocaleDateString("en-CA"),d0=new Date();d0.setHours(0,0,0,0);const seeInv=me.role=="owner"||can("view_invoices");
const[{data:ap},{data:iv},{data:oi},{data:dr}]=await Promise.all([sb.from("appointments").select("id,ticket_no,status,called_at,customer_id,barber_id,customers(name),profiles(full_name),appointment_services(service_id,services(name))").eq("day",t).order("ticket_no"),seeInv?sb.from("invoices").select("total").gte("created_at",d0.toISOString()):Promise.resolve({data:null}),can("use_pos")?sb.from("open_invoices").select("chair"):Promise.resolve({data:null}),(me.role=="owner"||can("approve_discount"))?sb.from("discount_requests").select("id,chair,pct,subtotal,reason,profiles(full_name)").eq("status","pending"):Promise.resolve({data:null})]);
const A=ap||[];C.A=A;const by=k=>A.filter(a=>a.status==k),ci=by("checked_in"),ins=by("in_service"),up=by("upcoming"),dn=by("done").length,wait=up.length+ci.length;
const rev=iv?iv.reduce((x,r)=>x+(+r.total||0),0):null,h=new Date().getHours(),nm=(me.full_name||"").split(" ").slice(0,2).join(" "),wo=C.cfg.weekly_off,off=wo!=null&&wo!==""&&new Date().getDay()==+wo,open=!off&&h>=+C.cfg.open_hour&&h<+C.cfg.close_hour;
const nm2=a=>esc(a.customers?.name||"عميل"),svc=a=>(a.appointment_services||[]).map(x=>esc(x.services?.name||"")).filter(Boolean).join(" + "),att=[];
ci.forEach(a=>att.push(`<div class="row"><div><b>#${a.ticket_no} · ${nm2(a)}</b><div class="m">وصل وبينتظر${svc(a)?" · "+svc(a):""}</div></div><button class="btn s" onclick="setS(${a.id},'in_service')">ابدأ</button></div>`));
ins.forEach(a=>att.push(`<div class="row"><div><b>#${a.ticket_no} · ${nm2(a)}</b><div class="m">على الكرسي${a.profiles?.full_name?" · "+esc(a.profiles.full_name):""}${svc(a)?" · "+svc(a):""}</div></div>${can("use_pos")?`<button class="btn s" onclick="payAppt(${a.id})">دفع</button>`:""}</div>`));
(dr||[]).forEach(r=>att.push(`<div class="row"><div><b>طلب خصم ${r.pct}% · كرسي ${r.chair||"-"}</b><div class="m">${esc(r.profiles?.full_name||"")}${r.reason?" · "+esc(r.reason):""}</div></div><div><button class="btn s" onclick="decideD(${r.id},true)">موافقة</button> <button class="btn s g" onclick="decideD(${r.id},false)">رفض</button></div></div>`));
if(oi&&oi.length)att.push(`<div class="row"><div><b>${oi.length} فاتورة مفتوحة</b><div class="m">على الكراسي ومستنية الدفع</div></div><button class="btn s" onclick="go('pos')">افتح الكاشير</button></div>`);
if(C.annN>0)att.push(`<div class="row"><div><b>${C.annN} إعلان جديد</b><div class="m">لسه ما اتقراش</div></div><button class="btn s g" onclick="go('ann')">اقرأ</button></div>`);
const nxt=up.slice(0,4).map(a=>`<div class="row"><div><b>#${a.ticket_no} · ${nm2(a)}</b><div class="m">${a.called_at?"مستدعى":"قادم"}${svc(a)?" · "+svc(a):""}</div></div>${!a.called_at&&can("manage_appts")?`<button class="btn s g" onclick="homeCall(${a.id})">استدعاء</button>`:""}</div>`).join("");
const acts=[can("use_pos")?`<button class="btn" onclick="go('pos')">بيع جديد</button>`:"",can("manage_appts")?`<button class="btn g" onclick="qa('appts','admForm','adm')">حجز إداري</button>`:"",can("view_customers")?`<button class="btn g" onclick="qa('cust','addCustForm','ac')">عميل جديد</button>`:"",can("manage_appts")?`<button class="btn g" onclick="go('appts')">إدارة الدور</button>`:""].join("");
put(`<div class="cc-hello"><div class="m">${new Date().toLocaleDateString("ar-EG",{weekday:"long",day:"numeric",month:"long"})}</div><h1>${h<12?"صباح الخير":"مساء الخير"}${nm?"، "+esc(nm):""}</h1><span class="tag ${open?"st-done":"st-no_show"}">${off?"إجازة النهارده":open?"الصالون مفتوح":"الصالون مقفول"}</span></div>
${me.role=="owner"||can("view_customers")?`<input id="gs" placeholder="ابحث: عميل، موبايل، فاتورة، خدمة، موظف" oninput="gsDeb()" style="margin-top:12px"><div id="gsr"></div>`:""}<div class="cc-grid"><div class="box cc-stat" role="button" style="cursor:pointer" onclick="dsAppts(['upcoming','checked_in'],'في الدور')"><div class="cc-l">في الدور</div><div class="cc-n">${wait}</div></div><div class="box cc-stat" role="button" style="cursor:pointer" onclick="dsAppts(['in_service'],'على الكراسي')"><div class="cc-l">على الكراسي</div><div class="cc-n">${ins.length}</div></div><div class="box cc-stat" role="button" style="cursor:pointer" onclick="dsAppts(['done'],'خلصوا النهارده')"><div class="cc-l">خلصوا النهارده</div><div class="cc-n">${dn}</div></div>${rev!=null?`<div class="box cc-stat" role="button" style="cursor:pointer" onclick="dsToday()"><div class="cc-l">إيراد اليوم</div><div class="cc-n">${fm(rev)}</div><div class="m">${iv.length} فاتورة</div></div>`:`<div class="box cc-stat" role="button" style="cursor:pointer" onclick="dsAppts(null,'حجوزات اليوم')"><div class="cc-l">حجوزات اليوم</div><div class="cc-n">${A.length}</div></div>`}</div>
<h2>محتاج انتباهك</h2>${att.length?att.join(""):`<p class="m">مفيش حاجة محتاجة انتباهك دلوقتي ✓</p>`}
${nxt?`<h2>الدور الجاي</h2>${nxt}`:A.length?"":`<p class="m">مفيش حجوزات النهارده لسه.</p>`}
${acts?`<h2>إجراءات سريعة</h2><div class="cc-act">${acts}</div>`:""}`);
clearInterval(C.poll);C.poll=setInterval(()=>{if(tab=="home"&&!($("gs")&&$("gs").value)){$("app").classList.add("still");V.home()}},30000)};
async function tk(f,id){const{error}=await sb.rpc(f,{p_id:id});error?toast(error.message):(tab=="appts"?go("appts"):C.reload())}
async function loadV(){const P=C.P,keep=P.rid;P.rid="";P.vs=[];if(P.cid&&C.cfg.ff_loyalty!==false){const{data}=await sb.from("loyalty_redemptions").select("id,code,loyalty_rewards(name)").eq("customer_id",P.cid).eq("status","active");P.vs=data||[];if(keep&&P.vs.some(v=>String(v.id)==String(keep)))P.rid=String(keep)}drawPos()}
const getPos=()=>new Promise(r=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>r({lat:p.coords.latitude,lng:p.coords.longitude}),()=>r({}),{enableHighAccuracy:true,timeout:12000,maximumAge:0}):r({}));
async function att(f){if(C.attBusy)return;C.attBusy=1;const bs=[...document.querySelectorAll('[onclick^="att("]')];bs.forEach(b=>b.disabled=true);let ok=false;try{toast("بنحدد موقعك...");const g=await getPos();const{data,error}=await sb.rpc(f,{p_lat:g.lat??null,p_lng:g.lng??null});if(error){const m=error.message||"";toast(/duplicate key|unique/i.test(m)?"حضورك متسجل قبل كده":m)}else{ok=true;toast(data);await C.reload()}}finally{C.attBusy=0;if(!ok)bs.forEach(b=>b.disabled=false)}}
