const RST={book:[["queue","تصفير الدور الحالي (مسح كل الحجوزات غير المنتهية)"],["appointments","مسح كل الحجوزات وتقييماتها"]],staff:[["attendance","تصفير سجل الحضور"],["staff_tx","تصفير السحب والخصومات والمكافآت"]],pos:[["invoices","مسح كل الفواتير"]],stock:[["stock","تصفير كميات المخزون وحركاته"]],loy:[["loyalty","تصفير نقاط وكوبونات كل العملاء"]],danger:[["reviews","مسح كل التقييمات"],["expenses","مسح كل المصروفات"],["finance","مسح كل بيانات المالية (قفل الخزنة، الموردين، المشتريات، صرف الرواتب)"],["customers","مسح كل العملاء وبياناتهم"],["all","تصفير كل البيانات (فواتير، حجوزات، عملاء، حضور، مخزون، نقاط، مصروفات)"]]};
const BK_TABLES=["profiles","app_settings","services","products","stock_movements","customers","appointments","appointment_services","invoices","invoice_items","reviews","expenses","staff_transactions","staff_shifts","staff_leaves","attendance","loyalty_ledger","loyalty_rewards","loyalty_redemptions","expense_categories","suppliers","purchases","purchase_items","supplier_payments","salary_payments","cash_moves","cash_closings"];
const BK_ORDER={app_settings:["key"],appointment_services:["appointment_id","service_id"]};
async function bkTable(t){const ord=BK_ORDER[t]||["id"];
  for(const useOrd of [true,false]){let all=[],from=0,err=null;
    for(;;){let q=sb.from(t).select(t=="profiles"?PCOLS:"*");if(useOrd)ord.forEach(c=>q=q.order(c));const{data,error}=await q.range(from,from+999);
      if(error){err=error;break}all.push(...data);if(data.length<1000)break;from+=1000}
    if(!err){if(t=="profiles")await addSalary(all);return{rows:all}}if(!useOrd)return{error:err.message}}}
async function backupAll(){const btn=$("bkb"),msg=$("bkm");btn.disabled=true;
  const out={app:"salon-backup",version:1,created_at:new Date().toISOString(),tables:{},errors:{}};let rows=0;
  for(const t of BK_TABLES){btn.textContent="بنسحب: "+t+"…";const r=await bkTable(t);if(r.error)out.errors[t]=r.error;else{out.tables[t]=r.rows;rows+=r.rows.length}}
  const n=Object.keys(out.tables).length,bad=Object.keys(out.errors);
  if(!n){btn.disabled=false;btn.textContent="⬇️ تنزيل نسخة احتياطية الآن";return msg.textContent="فشل السحب: "+(bad.map(k=>k+" ("+out.errors[k]+")").join("، "))}
  const day=new Date().toLocaleDateString("en-CA"),blob=new Blob([JSON.stringify(out)],{type:"application/json"}),a=document.createElement("a");
  a.href=URL.createObjectURL(blob);a.download="salon-backup-"+day+".json";document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),4000);
  try{localStorage.setItem("salon_last_backup",new Date().toISOString())}catch(e){}
  btn.disabled=false;btn.textContent="⬇️ تنزيل نسخة احتياطية الآن";
  msg.textContent=`تم ✓ ${n} جدول · ${rows} سجل`+(bad.length?` — مقدرناش نسحب: ${bad.join("، ")}`:"");toast(bad.length?"النسخة نزلت بس فيها جداول ناقصة":"تم تنزيل النسخة الاحتياطية ✓")}
const lastBk=()=>{let d=null;try{d=localStorage.getItem("salon_last_backup")}catch(e){}return d?"آخر نسخة من الجهاز ده: "+new Date(d).toLocaleString("ar-EG"):"لسه معملتش نسخة من الجهاز ده."};
// ===== النظام المالي: الخزنة اليومية + الموردين والمشتريات + الرواتب + الأرباح الشهرية + Excel =====
const paySrc=v=>`<option value="drawer" ${v!="other"?"selected":""}>من درج الكاش</option><option value="other" ${v=="other"?"selected":""}>من برا الدرج (بنك/محفظة)</option>`;
const mAr=d=>new Date(d+"T00:00").toLocaleDateString("ar-EG",{month:"long",year:"numeric"});
const monthR=ym=>{const[y,m]=ym.split("-").map(Number);return[new Date(y,m-1,1),new Date(y,m,1)]};
const CASHK=[["cash","كاش"],["card","كارت"],["wallet","محفظة"]];
const errBox=(box,e)=>{box.innerHTML=`<p class="m">${esc(e.message||e)} — لو الرسالة عن جدول أو دالة مش موجودة، شغّل patch9.sql في Supabase الأول.</p>`};

// ---------- الخزنة ----------
function closeCard(r){return `<div class="box">${tbl(["","المتوقع","المعدود","الفرق"],CASHK.map(([k,l])=>{const d=+r["diff_"+k];return [l,fm(r["expected_"+k]),fm(r["counted_"+k]),`<b style="color:${d==0?"var(--ok)":"var(--red)"}">${d==0?"مظبوط ✓":(d>0?"زيادة ":"عجز ")+fm(Math.abs(d))}</b>`]}))}</div>`}
V.cash=async()=>{const own=me.role=="owner",today=ymd(new Date());if(!own||!C.cd)C.cd=today;const day=C.cd;
  const[{data:closed,error:e0},{data:sm},{data:cl},{data:mv}]=await Promise.all([sb.rpc("is_day_closed",{p_day:day}),own?sb.rpc("day_summary",{p_day:day}):{data:null},own?sb.from("cash_closings").select("*").order("day",{ascending:false}).limit(30):{data:null},own?sb.from("cash_moves").select("*").eq("day",day).order("id"):{data:null}]);
  if(e0)return put(`<h1>الخزنة</h1><p class="m">${esc(e0.message)} — شغّل patch9.sql في Supabase الأول.</p>`);
  let h=`<h1>الخزنة</h1>`;
  if(own)h+=`<div id="kpi">${SK}</div><h2>الدرج وقفل اليوم</h2>`;
  if(own)h+=`<div class="chips" style="align-items:center"><input type="date" id="cdate" value="${day}" max="${today}" style="width:auto;margin:0" onchange="C.cd=this.value||null;V.cash()"><button class="btn s g" onclick="C.cd=null;V.cash()">اليوم</button></div>`;
  if(sm){const L=[["رصيد أول اليوم",sm.opening],["مبيعات كاش",sm.cash_sales],["مصروفات من الدرج",-sm.exp_cash],["مشتريات كاش",-sm.pur_cash],["تسديد موردين",-sm.sup_cash],["رواتب مصروفة",-sm.sal_cash],["سحب موظفين (سلف)",-sm.adv_cash],["سحب من الدرج",-sm.moves_out],["إضافة للدرج",sm.moves_in]].filter(r=>+r[1]||r[0]=="رصيد أول اليوم");
    h+=`<h2>المتوقع في الدرج (${sm.invoices} فاتورة)</h2><div class="box">${L.map(r=>`<div style="display:flex;justify-content:space-between;padding:3px 0"><span>${r[0]}</span><span>${fm(r[1])}</span></div>`).join("")}<div style="display:flex;justify-content:space-between;padding:6px 0 0;font-weight:800;border-top:1px solid var(--line);margin-top:4px"><span>الكاش المتوقع</span><span>${fm(sm.expected_cash)}</span></div></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">${kc("مبيعات كارت",fm(sm.card_sales),"","dsDayPay('card')")}${kc("مبيعات محفظة",fm(sm.wallet_sales),"","dsDayPay('wallet')")}</div>`}
  const row=C.cres&&C.cres.day==day?C.cres:(cl||[]).find(x=>x.day==day);
  if(closed||row)h+=`<h2>اتقفل يوم ${day}</h2>`+(row?closeCard(row):`<p class="m">اليوم ده اتقفل قبل كده.</p>`);
  else h+=`<h2>قفل اليوم</h2><div class="box"><p class="m" style="margin-top:0">${own?"اكتب اللي اتعدّ فعلًا. النظام بيقارنه بالمتوقع ويطلّع الفرق.":"عدّ اللي في الدرج واكتب الأرقام. النظام هيحسب الفرق لوحده."}</p><input id="kc_cash" type="number" inputmode="decimal" placeholder="الكاش اللي في الدرج"><input id="kc_card" type="number" inputmode="decimal" placeholder="إجمالي الكارت (من تقرير الماكينة)"><input id="kc_wallet" type="number" inputmode="decimal" placeholder="إجمالي المحفظة"><input id="kc_note" placeholder="ملاحظة (اختياري)">${own?`<input id="kc_open" type="number" inputmode="decimal" placeholder="رصيد أول اليوم (سيبه فاضي = رصيد آخر قفل ${sm?sm.opening:0})">`:""}<button class="btn" style="width:100%" onclick="doClose()">قفل اليوم</button></div>`;
  if(own){h+=`<h2>سحب / إضافة للدرج — ${day}</h2><div class="box"><select id="mv_k"><option value="withdraw">سحب من الدرج (مالك / إيداع بنك)</option><option value="deposit">إضافة للدرج (فكة / ضخ)</option></select><input id="mv_a" type="number" inputmode="decimal" placeholder="المبلغ"><input id="mv_n" placeholder="ملاحظة (اختياري)"><button class="btn s" onclick="addMove()">حفظ</button></div>`+(mv||[]).map(m=>`<div class="row"><div><b>${m.kind=="withdraw"?"سحب":"إضافة"} ${fm(m.amount)}</b><div class="m">${esc(m.note||"")}</div></div><button class="btn s g" onclick="delMove(${m.id})">حذف</button></div>`).join("");
    h+=`<h2>آخر عمليات القفل</h2>`+((cl||[]).length?cl.map(x=>`<details class="row"><summary><b>${x.day}</b> · <span style="color:${+x.diff_cash==0?"var(--ok)":"var(--red)"}">${+x.diff_cash==0?"الكاش مظبوط":(+x.diff_cash>0?"زيادة ":"عجز ")+fm(Math.abs(x.diff_cash))}</span></summary>${closeCard(x)}<div class="m">رصيد أول اليوم ${fm(x.opening)}${x.note?" · "+esc(x.note):""}</div><button class="btn s g" style="margin-top:8px" onclick="delClose(${x.id})">مسح القفل (لإعادته)</button></details>`).join(""):`<p class="m">لسه مفيش عمليات قفل.</p>`)}
  put(h);if(own)showKpi()};
async function doClose(){const g=id=>{const v=$(id).value;return v===""?NaN:parseFloat(v)},c=g("kc_cash"),cd=g("kc_card"),w=g("kc_wallet");
  if([c,cd,w].some(x=>isNaN(x)||x<0))return toast("اكتب الكاش والكارت والمحفظة (اكتب 0 لو مفيش)");
  const op=$("kc_open")?$("kc_open").value:"";if(!confirm("تقفل اليوم؟ مش هتقدر تعدّل بعد كده."))return;
  const{data,error}=await sb.rpc("close_day",{p_day:C.cd||ymd(new Date()),p_counted_cash:c,p_counted_card:cd,p_counted_wallet:w,p_opening:op===""?null:parseFloat(op),p_note:$("kc_note").value||null});
  if(error)return toast(error.message);C.cres=data;toast("تم قفل اليوم ✓");V.cash()}
async function delClose(id){if(!confirm("تمسح القفل ده عشان تعيده؟"))return;const{error}=await sb.from("cash_closings").delete().eq("id",id);error?toast(error.message):(C.cres=null,V.cash())}
async function addMove(){const a=parseFloat($("mv_a").value);if(!(a>0))return toast("اكتب المبلغ");const{error}=await sb.from("cash_moves").insert({day:C.cd||ymd(new Date()),kind:$("mv_k").value,amount:a,note:$("mv_n").value||null});error?toast(error.message):(toast("تم ✓"),V.cash())}
function delMove(id){return ownerDel("cash_moves",id,()=>V.cash(),"حذف الحركة؟")}

// ---------- المالية (للمالك) ----------
V.fin=async()=>{C.fs=C.fs||"pur";const FS=[["pur","الموردين والمشتريات"],["pay","الرواتب"],["mon","أرباح شهرية"],["cat","تصنيفات المصروفات"]];
  put(`<h1>المالية</h1><div class="chips">${FS.map(x=>`<button class="chip ${C.fs==x[0]?"sel":""}" onclick="C.fs='${x[0]}';V.fin()">${x[1]}</button>`).join("")}</div><div id="fb">${SK}</div>`);
  try{await({pur:finPur,pay:finPay,mon:finMon,cat:finCat})[C.fs]()}catch(e){const b=$("fb");if(b)b.innerHTML=`<p class="m">حصلت مشكلة في تحميل القسم: ${esc(e.message||e)}</p><button class="btn g" onclick="V.fin()">إعادة المحاولة</button>`}};

async function finPur(){const box=$("fb");const[{data:sp,error},{data:pu},{data:allp},{data:py},{data:pr}]=await Promise.all([sb.from("suppliers").select("*").order("name"),sb.from("purchases").select("*,suppliers(name),purchase_items(name,qty)").order("bought_on",{ascending:false}).order("id",{ascending:false}).limit(40),sb.from("purchases").select("supplier_id,total,paid"),sb.from("supplier_payments").select("id,supplier_id,amount,paid_on,note,suppliers(name)").order("paid_on",{ascending:false}).order("id",{ascending:false}),sb.from("products").select("id,name,cost").eq("active",true).order("name")]);
  if(error)return errBox(box,error);
  const bal={};(allp||[]).forEach(p=>{if(p.supplier_id)bal[p.supplier_id]=(bal[p.supplier_id]||0)+(+p.total)-(+p.paid)});(py||[]).forEach(p=>{bal[p.supplier_id]=(bal[p.supplier_id]||0)-(+p.amount)});
  C.fp={sp:sp||[],pr:pr||[]};
  box.innerHTML=`<h2>الموردين</h2>${(sp||[]).map(s=>{const b=bal[s.id]||0;return `<div class="row"><div><b>${esc(s.name)}</b><div class="m">${esc(s.phone||"")}${b>0?` · <span style="color:var(--red)">مستحق له ${fm(b)}</span>`:b<0?` · له رصيد عندنا ${fm(-b)}`:""}</div></div><button class="btn s g" onclick="supPayForm(${s.id})">تسديد</button></div><div id="sp${s.id}"></div>`}).join("")||`<p class="m">مفيش موردين لسه.</p>`}<div class="box" style="margin-top:8px"><input id="sn_n" placeholder="اسم مورد جديد"><input id="sn_p" type="tel" placeholder="موبايل (اختياري)"><button class="btn s" onclick="addSup()">+ إضافة مورد</button></div>
${(py||[]).length?`<h2>آخر التسديدات</h2>`+(py||[]).slice(0,15).map(p=>`<div class="row"><div><b>${fm(p.amount)}</b> · ${esc(p.suppliers?.name||"")}<div class="m">${p.paid_on}${p.note?" · "+esc(p.note):""}</div></div><button class="btn s g" onclick="ownerDel('supplier_payments','${p.id}',()=>V.fin(),'تحذف التسديد ده؟')">حذف</button></div>`).join(""):""}<h2>فاتورة شراء</h2><button class="btn" onclick="purForm()">+ فاتورة شراء جديدة</button><div id="pf"></div>
<h2>آخر المشتريات</h2>${(pu||[]).map(p=>`<div class="row"><div><b>${esc(p.suppliers?.name||"بدون مورد")}</b> · ${fm(p.total)}<div class="m">${p.bought_on} · ${p.kind=="stock"?"بضاعة مخزون":"مستلزمات"} · ${(p.purchase_items||[]).map(i=>esc(i.name)+" ×"+(+i.qty)).join("، ")}${+p.paid<+p.total?` · <span style="color:var(--red)">متبقي ${fm(p.total-p.paid)}</span>`:""}</div></div><button class="btn s g" onclick="voidPur(${p.id})">إلغاء</button></div>`).join("")||`<p class="m">مفيش مشتريات.</p>`}`}
async function addSup(){const n=$("sn_n").value.trim();if(n.length<2)return toast("اكتب اسم المورد");const{error}=await sb.from("suppliers").insert({name:n,phone:$("sn_p").value.trim()||null});error?toast(error.code=="23505"?"المورد ده موجود":error.message):(toast("تم ✓"),V.fin())}
function supPayForm(id){const e=$("sp"+id);if(e.innerHTML)return e.innerHTML="";e.innerHTML=`<div class="box" style="margin-bottom:10px"><input id="spa${id}" type="number" inputmode="decimal" placeholder="المبلغ"><select id="sps${id}">${paySrc("drawer")}</select><input id="spn${id}" placeholder="ملاحظة (اختياري)"><button class="btn s" onclick="saveSupPay(${id})">حفظ التسديد</button></div>`}
async function saveSupPay(id){const a=parseFloat($("spa"+id).value);if(!(a>0))return toast("اكتب المبلغ");const{error}=await sb.from("supplier_payments").insert({supplier_id:id,amount:a,paid_from:$("sps"+id).value,note:$("spn"+id).value||null,paid_on:ymd(new Date())});error?toast(error.message):(toast("تم التسديد ✓"),V.fin())}
function purForm(){C.pf={sup:"",kind:"stock",date:ymd(new Date()),items:[{product_id:"",name:"",qty:1,unit_cost:""}],paid:"",paid_from:"drawer",upd:false,note:""};drawPur()}
function pfTot(){return C.pf.items.reduce((a,i)=>a+(+i.qty||0)*(+i.unit_cost||0),0)}
function pfSet(i,k,v,quiet){const it=C.pf.items[i];it[k]=v;if(k=="product_id"){const p=C.fp.pr.find(x=>x.id==v);if(p&&!it.unit_cost)it.unit_cost=p.cost}if(quiet){const t=$("pf_t");if(t)t.textContent=fm(pfTot())}else drawPur()}
function drawPur(){const f=C.pf,P=C.fp;
  $("pf").innerHTML=`<div class="box" style="margin-top:8px"><label class="m">المورد</label><select onchange="C.pf.sup=this.value"><option value="">بدون مورد</option>${P.sp.filter(s=>s.active).map(s=>`<option value="${s.id}" ${f.sup==s.id?"selected":""}>${esc(s.name)}</option>`).join("")}</select>
<label class="m">نوع الشراء</label><select onchange="C.pf.kind=this.value;C.pf.items=[{product_id:'',name:'',qty:1,unit_cost:''}];drawPur()"><option value="stock" ${f.kind=="stock"?"selected":""}>بضاعة للمخزون (بتزوّد الكمية)</option><option value="supplies" ${f.kind=="supplies"?"selected":""}>مستلزمات (بتتحسب مصروف)</option></select>
<input type="date" value="${f.date}" onchange="C.pf.date=this.value">
${f.items.map((it,i)=>`<div style="border-top:1px dashed var(--line);padding-top:8px;margin-top:8px">${f.kind=="stock"?`<select onchange="pfSet(${i},'product_id',this.value)"><option value="">اختار المنتج</option>${P.pr.map(p=>`<option value="${p.id}" ${it.product_id==p.id?"selected":""}>${esc(p.name)}</option>`).join("")}</select>`:`<input placeholder="اسم البند" value="${esc(it.name)}" oninput="pfSet(${i},'name',this.value,1)">`}<div class="chips" style="margin:0"><input type="number" inputmode="decimal" placeholder="الكمية" value="${it.qty}" style="width:90px" oninput="pfSet(${i},'qty',this.value,1)"><input type="number" inputmode="decimal" placeholder="سعر الوحدة" value="${it.unit_cost}" style="width:120px" oninput="pfSet(${i},'unit_cost',this.value,1)">${f.items.length>1?`<button class="btn s g" onclick="C.pf.items.splice(${i},1);drawPur()">حذف</button>`:""}</div></div>`).join("")}
<button class="btn s g" style="margin:8px 0" onclick="C.pf.items.push({product_id:'',name:'',qty:1,unit_cost:''});drawPur()">+ بند</button>
<div style="display:flex;justify-content:space-between;font-weight:800;margin-bottom:8px"><span>الإجمالي</span><span id="pf_t">${fm(pfTot())}</span></div>
<input type="number" inputmode="decimal" placeholder="المدفوع دلوقتي (اكتب 0 لو آجل)" value="${f.paid}" oninput="C.pf.paid=this.value"><select onchange="C.pf.paid_from=this.value">${paySrc(f.paid_from)}</select>
${f.kind=="stock"?`<label class="row" style="cursor:pointer"><span>حدّث تكلفة المنتج بسعر الشراء ده</span><input type="checkbox" ${f.upd?"checked":""} onchange="C.pf.upd=this.checked" style="width:22px;height:22px;margin:0"></label>`:""}
<input placeholder="ملاحظة (اختياري)" value="${esc(f.note)}" oninput="C.pf.note=this.value"><div class="chips"><button class="btn" onclick="savePur()">حفظ الفاتورة</button><button class="btn g" onclick="$('pf').innerHTML=''">إلغاء</button></div></div>`}
async function savePur(){const f=C.pf;if(f.paid==="")return toast("اكتب المدفوع (اكتب 0 لو آجل)");
  const items=f.items.map(i=>({product_id:f.kind=="stock"?(i.product_id||null):null,name:i.name,qty:+i.qty,unit_cost:+i.unit_cost}));
  const{error}=await sb.rpc("record_purchase",{p_supplier:f.sup?+f.sup:null,p_date:f.date,p_kind:f.kind,p_items:items,p_paid:+f.paid,p_paid_from:f.paid_from,p_note:f.note||null,p_update_cost:!!f.upd});
  error?toast(error.message):(toast("تم تسجيل الفاتورة ✓"),V.fin())}
async function voidPur(id){if(!confirm("تلغي فاتورة الشراء دي؟ هترجّع المخزون وتمسح المصروف المرتبط بيها."))return;const{error}=await sb.rpc("void_purchase",{p_id:id});error?toast(error.message):(toast("تم الإلغاء"),V.fin())}

async function finPay(){const box=$("fb");const now=ymd(new Date());C.pm=C.pm||now.slice(0,7)+"-01";const[a,b]=monthR(C.pm);
  const{data:st,error}=await sb.from("profiles").select("id,full_name,role").neq("role","owner").neq("role","customer").order("full_name");if(!error)await addSalary(st);if(error)return errBox(box,error);
  const[sums,{data:pays,error:e2}]=await Promise.all([Promise.all((st||[]).map(s=>sb.rpc("staff_summary",{p_staff:s.id,p_from:a.toISOString(),p_to:b.toISOString()}))),sb.from("salary_payments").select("*,profiles(full_name)").eq("period",C.pm).order("id",{ascending:false})]);
  if(e2)return errBox(box,e2);
  const paid={};(pays||[]).forEach(p=>paid[p.staff_id]=(paid[p.staff_id]||0)+(+p.amount));
  const rows=(st||[]).map((s,i)=>{const net=sums[i].data?.[0]?.net,due=net==null?0:+net,pd=paid[s.id]||0,rem=Math.max(0,due-pd);return{s,due,pd,rem}});
  const T=rows.reduce((o,r)=>({due:o.due+r.due,pd:o.pd+r.pd,rem:o.rem+r.rem}),{due:0,pd:0,rem:0});
  box.innerHTML=`<div class="chips" style="align-items:center"><input type="month" value="${C.pm.slice(0,7)}" style="width:auto;margin:0" onchange="C.pm=(this.value||'${now.slice(0,7)}')+'-01';V.fin()"></div><div class="m" style="margin:6px 0">المستحق = الراتب الثابت + العمولة + المكافآت − السحب − الخصومات (عن ${mAr(C.pm)})</div>
<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${kc("المستحق",fm(T.due))}${kc("اتصرف",fm(T.pd),"var(--ok)")}${kc("المتبقي",fm(T.rem),T.rem>0?"var(--red)":"inherit")}</div>
<h2>الموظفين</h2>${tbl(["الموظف","المستحق","اتصرف","المتبقي",""],rows.map(r=>[`${esc(r.s.full_name)}<div class="m">${RL[r.s.role]||r.s.role}</div>`,fm(r.due),fm(r.pd),`<b style="color:${r.rem>0?"var(--red)":"var(--ok)"}">${fm(r.rem)}</b>`,`<button class="btn s" onclick="payForm('${r.s.id}',${r.rem})">صرف</button>`]))}<div id="pyf"></div>
<h2>سجل الصرف</h2>${(pays||[]).map(p=>`<div class="row"><div><b>${esc(p.profiles?.full_name||"—")}</b> · ${fm(p.amount)}<div class="m">${p.paid_on} · ${p.paid_from=="drawer"?"من الدرج":"من برا الدرج"}${p.note?" · "+esc(p.note):""}</div></div><button class="btn s g" onclick="delPay(${p.id})">حذف</button></div>`).join("")||`<p class="m">مفيش صرف الشهر ده.</p>`}`}
function payForm(id,rem){C.py=id;$("pyf").innerHTML=`<div class="box" style="margin-top:10px"><div class="m">صرف راتب</div><input id="py_a" type="number" inputmode="decimal" value="${rem||""}" placeholder="المبلغ"><select id="py_s">${paySrc("drawer")}</select><input id="py_n" placeholder="ملاحظة (اختياري)"><div class="chips"><button class="btn" onclick="savePay()">حفظ الصرف</button><button class="btn g" onclick="$('pyf').innerHTML=''">إلغاء</button></div></div>`;$("py_a").focus()}
async function savePay(){const a=parseFloat($("py_a").value);if(!(a>0))return toast("اكتب المبلغ");const{error}=await sb.from("salary_payments").insert({staff_id:C.py,period:C.pm,amount:a,paid_from:$("py_s").value,note:$("py_n").value||null,paid_on:ymd(new Date())});error?toast(error.message):(toast("تم صرف الراتب ✓"),V.fin())}
function delPay(id){return ownerDel("salary_payments",id,()=>V.fin(),"تحذف سجل الصرف ده؟")}

async function finMon(){const box=$("fb");const{data,error}=await sb.rpc("monthly_profit",{p_months:12});if(error)return errBox(box,error);const L=data||[];C.mon=L;
  box.innerHTML=`<h2>صافي الربح كل شهر</h2>${bars(L.slice().reverse(),x=>mAr(x.month),x=>Math.max(0,+x.profit))}<h2>التفاصيل</h2>${tbl(["الشهر","المبيعات","تكلفة","عمولات ورواتب","مصروفات","الصافي"],L.map(x=>[mAr(x.month),fm(x.revenue),fm(x.cogs),fm(+x.commissions+ +x.salaries+ +x.bonuses- +x.deductions),fm(x.expenses),`<b style="color:${+x.profit>=0?"var(--ok)":"var(--red)"}">${fm(x.profit)}</b>`]))}<div class="chips" style="margin-top:12px"><button class="btn g s" onclick="exportMonthly()">⬇ تصدير Excel</button></div>`}
async function finCat(){const box=$("fb");const{data,error}=await sb.from("expense_categories").select("*").order("id");if(error)return errBox(box,error);
  box.innerHTML=`<div class="m" style="margin-bottom:8px">التصنيفات دي بتظهر عند تسجيل مصروف. الرواتب مش تصنيف: بتتسجل من تاب "الرواتب" عشان ما تتحسبش مرتين.</div>${(data||[]).map(c=>`<div class="row"><b>${esc(c.name)}${c.active?"":" · موقوف"}</b><button class="btn s g" onclick="togCat(${c.id},${!c.active})">${c.active?"إيقاف":"تفعيل"}</button></div>`).join("")}<div class="box"><input id="cat_n" placeholder="تصنيف جديد"><button class="btn s" onclick="addCat()">+ إضافة</button></div>`}
async function addCat(){const n=$("cat_n").value.trim();if(!n)return toast("اكتب اسم التصنيف");const{error}=await sb.from("expense_categories").insert({name:n});error?toast(error.code=="23505"?"التصنيف ده موجود":error.message):V.fin()}
async function togCat(id,v){await sb.from("expense_categories").update({active:v}).eq("id",id);V.fin()}

// ---------- تصدير Excel (SheetJS بيتحمّل وقت الضغط بس) ----------
function loadXlsx(){return new Promise((ok,no)=>{if(window.XLSX)return ok(window.XLSX);const s=document.createElement("script");s.src="https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";s.onload=()=>window.XLSX?ok(window.XLSX):no(new Error("مكتبة Excel ما اشتغلتش"));s.onerror=()=>no(new Error("مقدرناش نحمّل مكتبة Excel، اتأكد من النت"));document.head.appendChild(s)})}
function xSheet(X,wb,name,rows){const ws=X.utils.aoa_to_sheet(rows);ws["!cols"]=(rows[0]||[]).map((_,i)=>({wch:Math.min(40,Math.max(10,...rows.map(r=>String(r[i]??"").length+2)))}));X.utils.book_append_sheet(wb,ws,name.slice(0,31))}
const PAYL={cash:"كاش",card:"كارت",wallet:"محفظة"};
async function exportXlsx(){const d=C.rd,T=d.totals,[a,b]=C.rr,e=new Date(b);e.setDate(e.getDate()-1);let X;try{X=await loadXlsx()}catch(err){return toast(err.message)}
  toast("بنجهّز ملف Excel…");const da=ymd(a),db=ymd(b),A=a.toISOString(),B=b.toISOString();
  const[{data:inv},{data:pu},{data:sp},{data:cl}]=await Promise.all([sb.from("invoices").select("no,created_at,total,discount,payment_method,customers(name),profiles:barber_id(full_name),invoice_items(name,qty)").gte("created_at",A).lt("created_at",B).order("created_at"),sb.from("purchases").select("bought_on,kind,total,paid,note,suppliers(name)").gte("bought_on",da).lt("bought_on",db).order("bought_on"),sb.from("salary_payments").select("period,amount,paid_on,paid_from,note,profiles(full_name)").gte("paid_on",da).lt("paid_on",db).order("paid_on"),sb.from("cash_closings").select("*").gte("day",da).lt("day",db).order("day")]);
  const wb=X.utils.book_new();wb.Workbook={Views:[{RTL:true}]};const n=v=>+v||0;
  xSheet(X,wb,"الملخص",[["البند","القيمة"],["الفترة",da+" → "+ymd(e)],["المبيعات",n(T.revenue)],["تكلفة المنتجات المباعة",-n(T.cogs)],["عمولات الحلاقين",-n(T.commissions)],["رواتب ثابتة",-n(T.salaries)],["المكافآت",-n(T.bonuses)],["الخصومات على الموظفين",n(T.deductions)],["المصروفات",-n(T.expenses)],["صافي الربح",n(T.profit)],["عدد الفواتير",n(T.invoices)],["متوسط الفاتورة",n(T.avg)],["الخصومات للعملاء",n(T.discounts)]]);
  xSheet(X,wb,"الفواتير",[["رقم","التاريخ","العميل","الحلاق","البنود","الخصم","الإجمالي","الدفع"],...(inv||[]).map(i=>[i.no,new Date(i.created_at).toLocaleString("ar-EG"),i.customers?.name||"عابر",i.profiles?.full_name||"",(i.invoice_items||[]).map(x=>x.name+"×"+x.qty).join(" + "),n(i.discount),n(i.total),PAYL[i.payment_method]||i.payment_method])]);
  xSheet(X,wb,"يوم بيوم",[["اليوم","المبيعات"],...(d.by_day||[]).map(x=>[x.d,n(x.t)])]);
  xSheet(X,wb,"طرق الدفع",[["الطريقة","الفواتير","الإجمالي"],...(d.by_pay||[]).map(x=>[PAYL[x.m]||x.m,n(x.n),n(x.t)])]);
  xSheet(X,wb,"الخدمات",[["الخدمة","العدد","الإيراد"],...(d.services||[]).map(x=>[x.n,n(x.q),n(x.t)])]);
  xSheet(X,wb,"المنتجات",[["المنتج","العدد","الإيراد","الربح"],...(d.products||[]).map(x=>[x.n,n(x.q),n(x.t),n(x.p)])]);
  xSheet(X,wb,"الحلاقين",[["الحلاق","الزباين","المبيعات","العمولة","التقييم"],...(d.barbers||[]).map(x=>[x.n,n(x.cuts),n(x.sales),n(x.comm),x.rating||""])]);
  if((d.assistants||[]).length)xSheet(X,wb,"المساعدين",[["المساعد","خدمات","قيمتها","حصة المحل","راتب الفترة"],...d.assistants.map(x=>[x.n,n(x.svc),n(x.val),n(x.cut),n(x.sal)])]);
  xSheet(X,wb,"المصروفات",[["التاريخ","البند","المبلغ","مصدر الدفع","ملاحظة"],...(C.rx||[]).map(x=>[x.spent_on,x.category,n(x.amount),x.paid_from=="other"?"من برا الدرج":"من الدرج",x.note||""])]);
  xSheet(X,wb,"المشتريات",[["التاريخ","المورد","النوع","الإجمالي","المدفوع","ملاحظة"],...(pu||[]).map(p=>[p.bought_on,p.suppliers?.name||"",p.kind=="stock"?"بضاعة":"مستلزمات",n(p.total),n(p.paid),p.note||""])]);
  xSheet(X,wb,"صرف الرواتب",[["تاريخ الصرف","الموظف","عن شهر","المبلغ","المصدر","ملاحظة"],...(sp||[]).map(p=>[p.paid_on,p.profiles?.full_name||"",p.period,n(p.amount),p.paid_from=="other"?"من برا الدرج":"من الدرج",p.note||""])]);
  xSheet(X,wb,"قفل الخزنة",[["اليوم","رصيد أول","كاش متوقع","كاش معدود","فرق الكاش","كارت متوقع","كارت معدود","فرق الكارت","محفظة متوقع","محفظة معدود","فرق المحفظة","ملاحظة"],...(cl||[]).map(c=>[c.day,n(c.opening),n(c.expected_cash),n(c.counted_cash),n(c.diff_cash),n(c.expected_card),n(c.counted_card),n(c.diff_card),n(c.expected_wallet),n(c.counted_wallet),n(c.diff_wallet),c.note||""])]);
  X.writeFile(wb,`salon-report-${da}_${ymd(e)}.xlsx`);toast("تم تنزيل ملف Excel ✓")}
async function exportMonthly(){let X;try{X=await loadXlsx()}catch(err){return toast(err.message)}const wb=X.utils.book_new();wb.Workbook={Views:[{RTL:true}]};const n=v=>+v||0;
  xSheet(X,wb,"أرباح شهرية",[["الشهر","الفواتير","المبيعات","تكلفة المنتجات","العمولات","رواتب ثابتة","مكافآت","خصومات موظفين","المصروفات","صافي الربح"],...(C.mon||[]).map(x=>[x.month,n(x.invoices),n(x.revenue),n(x.cogs),n(x.commissions),n(x.salaries),n(x.bonuses),n(x.deductions),n(x.expenses),n(x.profit)])]);
  X.writeFile(wb,`salon-monthly-profit-${ymd(new Date())}.xlsx`);toast("تم تنزيل ملف Excel ✓")}

// ---------- كروت KPI في تاب الخزنة (للمالك): دخل / سحب / مصاريف / عمولات / بضاعة / الدرج — وكل كارت بيفتح تفاصيله ----------
const KR=[["today","اليوم"],["yesterday","أمس"],["week","7 أيام"],["month","الشهر"],["lastmonth","الشهر اللي فات"]];
const sumOf=(a,f)=>(a||[]).reduce((s,x)=>s+(+f(x)||0),0);
async function loadKpi(){const k=C.kr||"today",[a,b]=rangeR(k),e=new Date(b);e.setDate(e.getDate()-1);const f=ymd(a),t=ymd(e),A=a.toISOString(),B=b.toISOString();
  const[{data:dr,error},{data:st},{data:adv},{data:mv},{data:ex},{data:gp},{data:rd}]=await Promise.all([
    sb.rpc("drawer_range",{p_from:f,p_to:t}),
    sb.from("profiles").select("id,full_name,role").in("role",["barber","assistant","cashier"]).order("full_name"),
    sb.from("staff_transactions").select("staff_id,amount,note,created_at,profiles(full_name)").eq("kind","advance").gte("created_at",A).lt("created_at",B).order("created_at",{ascending:false}),
    sb.from("cash_moves").select("*").eq("kind","withdraw").gte("day",f).lte("day",t).order("day",{ascending:false}),
    sb.from("expenses").select("*").gte("spent_on",f).lte("spent_on",t).order("spent_on",{ascending:false}),
    sb.from("purchases").select("*,suppliers(name),purchase_items(name,qty)").eq("kind","stock").gte("bought_on",f).lte("bought_on",t).order("bought_on",{ascending:false}),
    sb.rpc("report_data",{p_from:A,p_to:B})]);
  if(error)return{error};
  const sums=await Promise.all((st||[]).filter(s=>s.role=="barber").map(s=>sb.rpc("staff_summary",{p_staff:s.id,p_from:A,p_to:B})));
  const bars=(st||[]).filter(s=>s.role=="barber").map((s,i)=>{const m=sums[i].data?.[0]||{};return{id:s.id,n:s.full_name,sales:+m.sales||0,cuts:+m.cuts||0,comm:+m.commission||0,adv:+m.advances||0,assist:+m.assistant_cuts||0}});
  return{k,f,t,A,B,dr,adv:adv||[],mv:mv||[],ex:ex||[],gp:gp||[],bars,cogs:+rd?.totals?.cogs||0}}
async function showKpi(){const box=$("kpi");if(!box)return;C.kp=await loadKpi();if(!$("kpi"))return;
  if(C.kp.error)return $("kpi").innerHTML=`<p class="m">${esc(C.kp.error.message)} — شغّل patch10.sql في Supabase الأول.</p>`;drawKpi()}
function kpiCards(P){const d=P.dr,wd=sumOf(P.adv,x=>x.amount)+sumOf(P.mv,x=>x.amount),exp=sumOf(P.ex,x=>x.amount),com=sumOf(P.bars,x=>x.comm),gd=sumOf(P.gp,x=>x.total);
  return[["inc","إجمالي الدخل",+d.revenue,"var(--ok)",d.invoices+" فاتورة"],["wd","إجمالي السحب",wd,"var(--red)",P.adv.length+P.mv.length+" عملية"],["exp","إجمالي المصاريف",exp,"var(--red)",P.ex.length+" بند"],["com","عمولات الصنايعية",com,"inherit",P.bars.length+" صنايعي"],["gd","البضاعة (مشتريات)",gd,"inherit",P.gp.length+" فاتورة"],["drw","اللي في الدرج (متوقع)",+d.expected_cash,+d.expected_cash>=0?"var(--gold2)":"var(--red)","كاش بس"]]}
function drawKpi(){const P=C.kp;if(!P||!$("kpi"))return;const d=P.dr,cards=kpiCards(P),sel=C.kd;
  const row=(l,v,b,a)=>`<div ${a?`role="button" onclick="${a}"`:""} style="${a?"cursor:pointer;color:var(--gold2);":""}display:flex;justify-content:space-between;padding:4px 0;${b?"font-weight:800;border-top:1px solid var(--line);margin-top:4px":""}"><span>${l}</span><span>${v}</span></div>`;
  let det="";
  if(sel=="inc"){const bs=P.bars.slice().sort((x,y)=>y.sales-x.sales);
    det=`<h2>الدخل حسب طريقة الدفع</h2><div class="box">${row("كاش",fm(d.cash_sales),0,"dsBar(null,'cash')")}${row("كارت",fm(d.card_sales),0,"dsBar(null,'card')")}${row("محفظة",fm(d.wallet_sales),0,"dsBar(null,'wallet')")}${row("الإجمالي ("+d.invoices+" فاتورة) — اضغط للفواتير",fm(d.revenue),1,"dsAll()")}</div><h2>مين اشتغل بكام</h2>${tbl(["الصنايعي","الزباين","الشغل (مبيعات)"],bs.map(x=>[`<a href="#" style="color:var(--gold2)" onclick="dsBar('${x.id}');return false">${esc(x.n)}</a>`,x.cuts,fm(x.sales)]).concat(bs.length?[[`<b>الإجمالي</b>`,sumOf(bs,x=>x.cuts),`<b>${fm(sumOf(bs,x=>x.sales))}</b>`]]:[]))}`}
  if(sel=="wd"){const by={};P.adv.forEach(x=>{const n=x.profiles?.full_name||"—";(by[n]=by[n]||{n,c:0,t:0});by[n].c++;by[n].t+=+x.amount});
    det=`<h2>سحب الموظفين (سلف) — مين سحب كام</h2>${tbl(["الاسم","مرات","إجمالي السحب"],Object.values(by).sort((x,y)=>y.t-x.t).map(x=>[esc(x.n),x.c,fm(x.t)]).concat(P.adv.length?[[`<b>الإجمالي</b>`,P.adv.length,`<b>${fm(sumOf(P.adv,x=>x.amount))}</b>`]]:[]))}<h2>تفاصيل السلف</h2>${P.adv.map(x=>`<div class="row"><div><b>${esc(x.profiles?.full_name||"—")}</b> · ${fm(x.amount)}<div class="m">${new Date(x.created_at).toLocaleString("ar-EG")}${x.note?" · "+esc(x.note):""}</div></div></div>`).join("")||`<p class="m">مفيش سلف في الفترة دي.</p>`}<h2>سحب من الدرج (مالك / إيداع بنك)</h2>${P.mv.map(x=>`<div class="row"><div><b>${fm(x.amount)}</b><div class="m">${x.day}${x.note?" · "+esc(x.note):""}</div></div></div>`).join("")||`<p class="m">مفيش سحب من الدرج في الفترة دي.</p>`}`}
  if(sel=="exp"){const by={};P.ex.forEach(x=>by[x.category]=(by[x.category]||0)+ +x.amount);
    det=`<h2>المصاريف حسب البند</h2>${tbl(["البند","الإجمالي"],Object.entries(by).sort((x,y)=>y[1]-x[1]).map(([c,t])=>[esc(c),fm(t)]).concat(P.ex.length?[[`<b>الإجمالي</b>`,`<b>${fm(sumOf(P.ex,x=>x.amount))}</b>`]]:[]))}<h2>التفاصيل</h2>${P.ex.map(x=>`<div class="row"><div><b>${esc(x.category)}</b> · ${fm(x.amount)}<div class="m">${x.spent_on}${x.note?" · "+esc(x.note):""}${x.purchase_id?" · من فاتورة شراء":""}${x.paid_from=="other"?" · من برا الدرج":""}</div></div></div>`).join("")||`<p class="m">مفيش مصاريف في الفترة دي.</p>`}`}
  if(sel=="com"){const bs=P.bars.slice().sort((x,y)=>y.comm-x.comm);
    det=`<h2>الشغل − السحب = الباقي لكل صنايعي</h2>${tbl(["الصنايعي","الشغل","العمولة","السحب","الباقي"],bs.map(x=>[`<a href="#" style="color:var(--gold2)" onclick="dsBar('${x.id}');return false">${esc(x.n)}</a>`,fm(x.sales),fm(x.comm),fm(x.adv),`<b style="color:${x.comm-x.adv>=0?"var(--ok)":"var(--red)"}">${fm(x.comm-x.adv)}</b>`]).concat(bs.length?[[`<b>الإجمالي</b>`,`<b>${fm(sumOf(bs,x=>x.sales))}</b>`,`<b>${fm(sumOf(bs,x=>x.comm))}</b>`,`<b>${fm(sumOf(bs,x=>x.adv))}</b>`,`<b>${fm(sumOf(bs,x=>x.comm-x.adv))}</b>`]]:[]))}<div class="m" style="margin-top:6px">الباقي = العمولة − السحب. العمولة محسوبة بعد خصم نسبة المساعدين${sumOf(bs,x=>x.assist)?" ("+fm(sumOf(bs,x=>x.assist))+" في الفترة دي)":""}. المكافآت والخصومات والرواتب الثابتة في تاب المالية ← الرواتب.</div>`}
  if(sel=="gd"){const tot=sumOf(P.gp,x=>x.total),pd=sumOf(P.gp,x=>x.paid);
    det=`<h2>مشتريات البضاعة</h2><div class="box">${row("إجمالي المشتريات",fm(tot))}${row("اتدفع",fm(pd))}${row("متبقي للموردين",fm(tot-pd),1)}${row("تكلفة البضاعة اللي اتباعت في الفترة",fm(P.cogs))}</div><h2>الفواتير</h2>${P.gp.map(p=>`<div class="row"><div><b>${esc(p.suppliers?.name||"بدون مورد")}</b> · ${fm(p.total)}<div class="m">${p.bought_on} · ${(p.purchase_items||[]).map(i=>esc(i.name)+" ×"+(+i.qty)).join("، ")}${+p.paid<+p.total?` · <span style="color:var(--red)">متبقي ${fm(p.total-p.paid)}</span>`:""}</div></div></div>`).join("")||`<p class="m">مفيش مشتريات بضاعة في الفترة دي.</p>`}<div class="m">مشتريات المستلزمات بتظهر في كارت المصاريف.</div>`}
  if(sel=="drw"){const L=[["رصيد أول الفترة (آخر قفل قبلها)",+d.opening],["مبيعات كاش",+d.cash_sales],["مصاريف من الدرج",-d.exp_cash],["مشتريات كاش",-d.pur_cash],["تسديد موردين",-d.sup_cash],["رواتب مصروفة",-d.sal_cash],["سحب موظفين (سلف)",-d.adv_cash],["سحب من الدرج",-d.moves_out],["إضافة للدرج",+d.moves_in]].filter(r=>+r[1]||r[0].startsWith("رصيد"));
    det=`<h2>إزاي طلع اللي في الدرج؟</h2><div class="box">${L.map(r=>row(r[0],fm(r[1]))).join("")}${row("المتوقع في الدرج",fm(d.expected_cash),1)}</div><div class="m" style="margin-top:6px">الكارت والمحفظة (${fm(+d.card_sales+ +d.wallet_sales)}) مش داخلين في الدرج. الحساب بيبدأ من الكاش اللي اتعدّ في آخر قفل قبل الفترة، ولو مفيش قفل بيبدأ من صفر.</div>`}
  $("kpi").innerHTML=`<div class="chips">${KR.map(x=>`<button class="chip ${P.k==x[0]?"sel":""}" onclick="C.kr='${x[0]}';C.kd=null;V.cash()">${x[1]}</button>`).join("")}</div><div class="m" style="margin:2px 0 8px">${P.f==P.t?P.f:P.f+" ← "+P.t}</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${cards.map(c=>`<button class="box" style="text-align:center;cursor:pointer;margin:0;width:100%;${sel==c[0]?"border-color:var(--gold2);box-shadow:0 0 0 1px var(--gold2) inset":""}" onclick="C.kd=C.kd=='${c[0]}'?null:'${c[0]}';drawKpi()"><div class="m">${c[1]}</div><div style="font-weight:800;font-size:19px;color:${c[3]}">${fm(c[2])}</div><div class="m" style="font-size:11px">${c[4]} · ${sel==c[0]?"اضغط للإغلاق":"اضغط للتفاصيل"}</div></button>`).join("")}</div>${det}`}
async function copyLink(p){const u=location.origin+p;try{await navigator.clipboard.writeText(u);toast("تم نسخ الرابط ✓")}catch(e){prompt("انسخ الرابط:",u)}}
// ===== واجهات patch11: الإعلانات / المتصدرين / التسوية / الراتب اليومي / الحجز الإداري / لم يحضر =====
async function annCount(){try{const[{data:L},{data:R}]=await Promise.all([sb.from("team_announcements").select("id,expires_at").eq("active",true).limit(100),sb.from("announcement_reads").select("announcement_id").eq("user_id",me.id)]);const rd=new Set((R||[]).map(x=>x.announcement_id));C.annN=(L||[]).filter(a=>(!a.expires_at||new Date(a.expires_at)>Date.now())&&!rd.has(a.id)).length}catch(e){C.annN=0}annDot()}
function annDot(){const b=document.querySelector('nav button[data-v~="ann"]');if(!b)return;const o=b.querySelector(".adot");if(o)o.remove();if(C.annN>0&&tab!="ann"){const i=document.createElement("i");i.className="adot";i.textContent=C.annN>9?"9+":C.annN;i.style.cssText="position:absolute;top:2px;right:10px;background:var(--red);color:#fff;border-radius:10px;font-size:10px;font-style:normal;padding:0 5px;line-height:16px";b.style.position="relative";b.appendChild(i)}}
V.ann=async()=>{const[{data:L,error},{data:R}]=await Promise.all([sb.from("team_announcements").select("*").order("pinned",{ascending:false}).order("created_at",{ascending:false}).limit(60),sb.from("announcement_reads").select("announcement_id").eq("user_id",me.id)]);
  if(error)return put(`<h1>الإعلانات</h1><p class="m">${esc(error.message)} — شغّل patch11.sql في Supabase الأول.</p>`);
  const rd=new Set((R||[]).map(x=>x.announcement_id)),post=can("manage_announcements"),live=a=>a.active&&(!a.expires_at||new Date(a.expires_at)>Date.now());
  put(`<h1>إعلانات الفريق</h1>${post?`<button class="btn s" onclick="annForm()">+ إعلان جديد</button><div id="af"></div>`:""}`+((L||[]).length?L.map(a=>{const mine=me.role=="owner"||a.created_by==me.id,un=live(a)&&!rd.has(a.id);return `<div class="box" style="margin-top:10px;${un?"border-color:var(--gold2);":""}${live(a)?"":"opacity:.55;"}"><div style="display:flex;justify-content:space-between;gap:8px"><b>${a.pinned?"📌 ":""}${esc(a.title)}</b>${un?`<span class="tag">جديد</span>`:""}</div><div style="white-space:pre-wrap;margin:6px 0">${esc(a.body)}</div><div class="m">${new Date(a.created_at).toLocaleString("ar-EG")}${a.expires_at?" · ينتهي "+new Date(a.expires_at).toLocaleDateString("ar-EG"):""}${live(a)?"":" · متوقف"}</div>${post&&mine?`<div class="chips" style="margin-top:8px"><button class="btn s g" onclick="annTog(${a.id},${!a.active})">${a.active?"إيقاف":"تفعيل"}</button><button class="btn s g" onclick="annPin(${a.id},${!a.pinned})">${a.pinned?"إلغاء التثبيت":"تثبيت"}</button><button class="btn s g" onclick="annDel(${a.id})">حذف</button></div>`:""}</div>`}).join(""):`<p class="m">مفيش إعلانات لسه.</p>`));
  await Promise.all((L||[]).filter(a=>live(a)&&!rd.has(a.id)).map(a=>sb.rpc("mark_announcement_read",{p_id:a.id})));C.annN=0;annDot()};
function annForm(){const e=$("af");if(e.innerHTML)return e.innerHTML="";e.innerHTML=`<div class="box" style="margin:10px 0"><input id="an_t" placeholder="عنوان الإعلان"><textarea id="an_b" rows="4" placeholder="نص الإعلان" style="width:100%"></textarea><label class="row" style="cursor:pointer"><span>تثبيت في الأول</span><input type="checkbox" id="an_p" style="width:22px;height:22px;margin:0"></label><label class="m">ينتهي في (اختياري)</label><input type="date" id="an_e"><div class="chips"><button class="btn" onclick="annSave()">نشر</button><button class="btn g" onclick="$('af').innerHTML=''">إلغاء</button></div></div>`}
async function annSave(){const t=$("an_t").value.trim(),b=$("an_b").value.trim(),ex=$("an_e").value;if(!t||!b)return toast("اكتب العنوان والنص");const{error}=await sb.from("team_announcements").insert({title:t,body:b,pinned:$("an_p").checked,expires_at:ex?new Date(ex+"T23:59:59").toISOString():null,created_by:me.id});error?toast(error.message):(toast("تم نشر الإعلان ✓"),V.ann())}
async function annTog(id,v){const{error}=await sb.from("team_announcements").update({active:v}).eq("id",id);error?toast(error.message):V.ann()}
async function annPin(id,v){const{error}=await sb.from("team_announcements").update({pinned:v}).eq("id",id);error?toast(error.message):V.ann()}
async function annDel(id){if(!confirm("تحذف الإعلان ده؟"))return;const{error}=await sb.from("team_announcements").delete().eq("id",id);error?toast(error.message):V.ann()}

V.lb=async()=>{C.lr=C.lr||"week";const[a,b]=rangeR(C.lr),e=new Date(b);e.setDate(e.getDate()-1);const{data,error}=await sb.rpc("barber_leaderboard",{p_from:ymd(a),p_to:ymd(e)});
  if(error)return put(`<h1>المتصدرين</h1><p class="m">${esc(error.message)} — شغّل patch11.sql في Supabase الأول.</p>`);
  const R=data.rows||[],W=data.weights||{},own=me.role=="owner",medal=r=>r==1?"🥇":r==2?"🥈":r==3?"🥉":"#"+r;
  put(`<h1>المتصدرين</h1><div class="chips">${[["today","اليوم"],["week","7 أيام"],["month","الشهر"],["lastmonth","الشهر اللي فات"]].map(x=>`<button class="chip ${C.lr==x[0]?"sel":""}" onclick="C.lr='${x[0]}';V.lb()">${x[1]}</button>`).join("")}</div><div class="m" style="margin:2px 0 8px">${data.from==data.to?data.from:data.from+" ← "+data.to}</div>`+
  (R.length?R.map(r=>`<div class="box" style="margin-top:8px;${r.barber_id==me.id?"border-color:var(--gold2)":""}"><div style="display:flex;justify-content:space-between;align-items:center"><b>${medal(r.rank)} ${esc(r.name)}${r.barber_id==me.id?" (إنت)":""}</b><b style="font-size:20px;color:var(--gold2)">${r.score==null?"—":r.score}</b></div><div class="m" style="margin-top:6px">${r.cuts} خدمة · ${r.customers} عميل${r.sales!=null?" · "+fm(r.sales):""}${r.avg_rating?" · ⭐ "+r.avg_rating+" ("+r.reviews+")":""}</div><div class="m">حضور ${r.attendance_days}/${r.expected_days} يوم${r.attendance_rate!=null?" ("+r.attendance_rate+"%)":""}${r.punctuality!=null?" · التزام بالمواعيد "+r.punctuality+"%":""}</div></div>`).join(""):`<p class="m">مفيش حلاقين.</p>`)+
  `<details class="box" style="margin-top:12px"><summary><b>إزاي بتتحسب الدرجة؟</b></summary>${(data.explain||[]).map(x=>`<div class="m" style="padding:3px 0">${esc(x)}</div>`).join("")}<div class="m" style="margin-top:6px">الأوزان: مبيعات ${W.sales||0} · خدمات ${W.services||0} · تقييم ${W.rating||0} · حضور ${W.attendance||0}</div>${own?`<div class="chips" style="margin-top:8px"><input id="lw_s" type="number" value="${W.sales||0}" style="width:72px" placeholder="مبيعات"><input id="lw_v" type="number" value="${W.services||0}" style="width:72px" placeholder="خدمات"><input id="lw_r" type="number" value="${W.rating||0}" style="width:72px" placeholder="تقييم"><input id="lw_a" type="number" value="${W.attendance||0}" style="width:72px" placeholder="حضور"><button class="btn s" onclick="saveLw()">حفظ الأوزان</button></div>`:""}</details>`)};
async function saveLw(){const v=id=>Math.max(0,+$(id).value||0),o={sales:v("lw_s"),services:v("lw_v"),rating:v("lw_r"),attendance:v("lw_a")};if(o.sales+o.services+o.rating+o.attendance<=0)return toast("لازم وزن واحد على الأقل أكبر من صفر");const{error}=await sb.from("app_settings").upsert({key:"leaderboard_weights",value:o});error?toast(error.message):(toast("تم حفظ الأوزان ✓"),V.lb())}

// ---- تسوية الحساب (في شاشة حساب الموظف للمالك) ----
async function stlLoad(id){if(!$("stl"))return;const[{data:pv,error},{data:hs}]=await Promise.all([sb.rpc("staff_settlement_preview",{p_staff:id}),sb.from("staff_settlements").select("*").eq("staff_id",id).order("created_at",{ascending:false}).limit(10)]);
  if(!$("stl"))return;if(error)return $("stl").innerHTML=`<h2>تسوية الحساب</h2><p class="m">${esc(error.message)}</p>`;const bal=+pv.balance;
  $("stl").innerHTML=`<h2>تسوية الحساب</h2><div class="box"><div class="m">من ${new Date(pv.from).toLocaleString("ar-EG")} لحد دلوقتي</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:8px">${kc("الصافي",fm(pv.net))}${kc("اتصرف",fm(pv.paid))}${kc("الرصيد",fm(bal),bal>0?"var(--red)":"var(--ok)")}</div><input id="st_a" type="number" inputmode="decimal" value="${bal>0?bal:""}" placeholder="مبلغ التسوية"><input id="st_r" placeholder="سبب التسوية (مطلوب)"><label class="row" style="cursor:pointer"><span>سجّل صرف كاش فعلي (يخصم من الخزنة)</span><input type="checkbox" id="st_p" style="width:22px;height:22px;margin:0"></label><select id="st_s">${paySrc("drawer")}</select><button class="btn" onclick="doSettle('${id}')">تنفيذ التسوية</button></div>${(hs||[]).map(h=>`<div class="row"><div><b>${fm(h.amount)}</b> · ${esc(h.reason)}<div class="m">${new Date(h.created_at).toLocaleString("ar-EG")} · الرصيد ${fm(h.balance_before)} ← ${fm(h.balance_after)}${h.salary_payment_id?" · اتسجّل صرف":""}</div></div><button class="btn s g" onclick="undoStl('${h.id}','${id}')">تراجع</button></div>`).join("")}`}
async function undoStl(sid,staff){if(!confirm("تلغي التسوية دي؟\nلو فيها صرف كاش هيتمسح كمان، والرصيد هيتحسب من جديد."))return;const{error}=await sb.rpc("admin_undo_settlement",{p_id:String(sid)});if(error)return toast(error.message);toast("اتلغت التسوية ✓");stlLoad(staff)}
async function delInv(id,force){if(!force&&!confirm("حذف الفاتورة دي؟\nالمخزون هيرجع، ونقاط العميل وزيارته هتتعكس، وأرقام المبيعات هتتعدّل."))return;const{data,error}=await sb.rpc("admin_void_invoice",{p_id:String(id),p_force:!!force});if(error)return toast(error.message);if(data?.needs_force){if(!confirm("الفاتورة دي من يوم "+data.day+" وهو مقفول في الخزنة.\nلو حذفتها أرقام اليوم هتبقى مختلفة عن اللي اتجرد.\nتكمّل؟"))return;return delInv(id,true)}toast("اتحذفت الفاتورة #"+(data?.no??"")+" ✓");V.inv()}
async function delAppt(id){if(!confirm("حذف الحجز ده نهائيًا؟\n(مختلف عن الإلغاء: بيتمسح من السجل بالكامل)"))return;const{data,error}=await sb.rpc("admin_delete_appointment",{p_id:String(id)});if(error)return toast(error.message);toast("اتحذف الحجز ✓");go("appts")}
async function doSettle(id){const a=parseFloat($("st_a").value),r=$("st_r").value.trim();if(!(a>0))return toast("اكتب مبلغ التسوية");if(!r)return toast("اكتب سبب التسوية");if(!confirm("تنفّذ التسوية؟ بتتسجل كسجل تدقيق ومينفعش تتمسح."))return;
  const{error}=await sb.rpc("settle_staff_account",{p_staff:id,p_amount:a,p_reason:r,p_record_payment:$("st_p").checked,p_paid_from:$("st_s").value});error?toast(error.message):(toast("تمت التسوية ✓"),stlLoad(id))}

// ---- الأجر اليومي والحضور (patch11 تعديل بالساعات / patch12 أجر يوم بالحضور) — واحدة بس عشان ما يتخصمش مرتين ----
async function dwgLoad(id){if(!$("dwg"))return;const[{data:pf},{data:ad},{data:dp,error:e12}]=await Promise.all([sb.from("staff_pay_profile").select("*").eq("staff_id",id).maybeSingle(),sb.from("salary_day_adjustments").select("*").eq("staff_id",id).order("day",{ascending:false}).limit(10),sb.from("assistant_day_pay").select("*").eq("staff_id",id).order("day",{ascending:false}).limit(10)]);
  if(!$("dwg"))return;C.has12=!e12;const p=pf||{daily_wage:0,standard_hours:12,adjust_by_attendance:false,deduct_rate:100,bonus_rate:0,pay_mode:"monthly",late_grace_min:10},mode=p.pay_mode=="daily_attendance"?"att":p.adjust_by_attendance?"adj":"none";C.pmode=mode;
  const on11=C.cfg.daily_salary_adjustment_enabled===true||C.cfg.daily_salary_adjustment_enabled==="true";
  $("dwg").innerHTML=`<h2>الأجر اليومي والحضور</h2><div class="box"><label class="m">طريقة الأجر اليومي (واحدة بس عشان ما يتخصمش مرتين)</label><select id="dw_m" onchange="dwMode()"><option value="none" ${mode=="none"?"selected":""}>بدون (راتب شهري / عمولة بس)</option><option value="adj" ${mode=="adj"?"selected":""}>تعديل بالساعات (خصم أو مكافأة على الفرق)</option>${C.has12?`<option value="att" ${mode=="att"?"selected":""}>أجر يوم بالحضور (بيتسجل أول ما يحضر، والتأخير بيتخصم)</option>`:""}</select><div id="dw_note" class="m" style="color:var(--red)"></div><label class="m">الأجر اليومي</label><input id="dw_w" type="number" inputmode="decimal" value="${+p.daily_wage}"><label class="m">ساعات اليوم الكاملة</label><input id="dw_h" type="number" inputmode="decimal" value="${+p.standard_hours}"><div id="dw_adj"><label class="m">نسبة الخصم من أجر الساعة لكل ساعة ناقصة %</label><input id="dw_d" type="number" inputmode="decimal" value="${+p.deduct_rate}"><label class="m">نسبة المكافأة من أجر الساعة لكل ساعة زيادة %</label><input id="dw_b" type="number" inputmode="decimal" value="${+p.bonus_rate}"></div><div id="dw_att"><label class="m">دقايق السماح في التأخير</label><input id="dw_g" type="number" inputmode="numeric" value="${+p.late_grace_min||10}"><div class="m">لو التأخير في حدود السماح مفيش خصم. بعده بيتخصم ساعة عن كل ساعة (أو جزء منها) من الأجر اليومي.</div></div><button class="btn" onclick="savePayProf('${id}')">حفظ</button><div class="chips" style="margin-top:10px;align-items:center"><input type="date" id="dw_day" value="${ymd(new Date())}" style="width:auto;margin:0"><button class="btn s g" onclick="applyDay('${id}')">${mode=="att"?"أعد حساب اليوم":"احسب تعديل اليوم"}</button></div></div>${(dp||[]).map(x=>`<div class="row"><div><b>${x.day}</b> · أجر ${fm(x.wage)} · اشتغل ${(x.worked_min/60).toFixed(1)} ساعة${x.closed?"":" (لسه شغال)"}<div class="m">${+x.deduction>0?"تأخير "+x.late_min+" دقيقة · خصم "+x.deduct_hours+" ساعة":"بدون خصم"}</div></div><b>${fm(x.net_day)}</b></div>`).join("")}${(ad||[]).map(x=>`<div class="row"><div><b>${x.day}</b> · ${+x.hours_worked} ساعة من ${+x.standard_hours}<div class="m">${esc(x.reason||"")}</div></div><b style="color:${+x.bonus>+x.deduction?"var(--ok)":+x.deduction>0?"var(--red)":"inherit"}">${+x.bonus>+x.deduction?"+"+fm(x.bonus-x.deduction):+x.deduction>0?"-"+fm(x.deduction):"0"}</b></div>`).join("")}`;
  C.on11=on11;dwMode()}
function dwMode(){const m=$("dw_m").value;$("dw_adj").style.display=m=="adj"?"":"none";$("dw_att").style.display=m=="att"?"":"none";$("dw_note").textContent=m=="adj"&&!C.on11?"الميزة مقفولة عامةً: فعّلها من الإعدادات ← الموظفين.":""}
async function savePayProf(id){const g=k=>{const e=$(k);return e?parseFloat(e.value):NaN},m=$("dw_m").value,w=g("dw_w"),h=g("dw_h"),d=g("dw_d"),b=g("dw_b"),gr=g("dw_g");
  if(isNaN(w)||w<0||isNaN(h)||!(h>0&&h<=24))return toast("راجع الأرقام (الساعات من 1 لـ 24)");if(m!="none"&&!(w>0))return toast("اكتب أجر يومي أكبر من صفر");
  let error;
  if(m=="att"){if(isNaN(gr)||gr<0||gr>59)return toast("السماح من 0 لـ 59 دقيقة");({error}=await sb.rpc("set_daily_pay",{p_staff:id,p_wage:w,p_hours:h,p_grace:Math.round(gr),p_enabled:true}))}
  else if(m=="adj"){if([d,b].some(x=>isNaN(x)||x<0))return toast("راجع النسب");const row={staff_id:id,daily_wage:w,standard_hours:h,adjust_by_attendance:true,deduct_rate:d,bonus_rate:b,updated_at:new Date().toISOString()};if(C.has12)row.pay_mode="monthly";({error}=await sb.from("staff_pay_profile").upsert(row,{onConflict:"staff_id"}))}
  else if(C.has12){({error}=await sb.rpc("set_daily_pay",{p_staff:id,p_wage:w,p_hours:h,p_grace:Math.round(gr)||10,p_enabled:false}))}
  else{({error}=await sb.from("staff_pay_profile").upsert({staff_id:id,daily_wage:w,standard_hours:h,adjust_by_attendance:false,updated_at:new Date().toISOString()},{onConflict:"staff_id"}))}
  error?toast(error.message):(toast("تم الحفظ ✓"),dwgLoad(id))}
async function applyDay(id){const day=$("dw_day").value;if(C.pmode=="att"){const{data,error}=await sb.rpc("recalc_day_pay",{p_staff:id,p_day:day});if(error)return toast(error.message);toast(data?(data.closed===false?"لسه شغال: الحساب بيتم عند الانصراف":+data.deduction>0?"اتحسب: خصم "+fm(data.deduction):"اتحسب: بدون خصم"):"مفيش أجر مسجّل في اليوم ده");return dwgLoad(id)}
  const{data,error}=await sb.rpc("apply_day_salary_adjustment",{p_staff:id,p_day:day});if(error)return toast(error.message);toast(data?("تم: "+(+data.bonus>+data.deduction?"مكافأة "+fm(data.bonus-data.deduction):+data.deduction>0?"خصم "+fm(data.deduction):"الساعات مطابقة")):"الميزة مقفولة أو التعديل بالساعات مش مفعّل للموظف");dwgLoad(id)}

