// ================= الإشعارات (Web Push + صوت) =================
IC.bell='<path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>';
const PUSH_OK=()=>"serviceWorker" in navigator&&"PushManager" in window&&"Notification" in window;
const isIOS=()=>/iphone|ipad|ipod/i.test(navigator.userAgent);
const b64u=s=>{const r=atob((s+"=".repeat((4-s.length%4)%4)).replace(/-/g,"+").replace(/_/g,"/"));return Uint8Array.from(r,c=>c.charCodeAt(0))};
const lsGet=k=>{try{return localStorage.getItem(k)}catch(e){return null}},lsSet=(k,v)=>{try{v==null?localStorage.removeItem(k):localStorage.setItem(k,v)}catch(e){}};
const pushSound=()=>lsGet("salon_sound")!="off",pushSetSound=v=>lsSet("salon_sound",v?null:"off");

// صوت التنبيه جوه التطبيق (بيتفتح بأول لمسة من المستخدم)
let _ac=null;
function unlockAudio(){try{_ac=_ac||new(window.AudioContext||window.webkitAudioContext)();if(_ac.state=="suspended")_ac.resume()}catch(e){}}
["pointerdown","keydown","touchstart"].forEach(ev=>addEventListener(ev,unlockAudio,{passive:true}));
function ding(urgent){if(!pushSound())return;try{unlockAudio();const t=_ac.currentTime,N=urgent?[[988,0],[1319,.16],[988,.34],[1319,.5]]:[[988,0],[1319,.15]];
N.forEach(([f,d])=>{const o=_ac.createOscillator(),g=_ac.createGain();o.type="sine";o.frequency.value=f;g.gain.setValueAtTime(0,t+d);g.gain.linearRampToValueAtTime(.35,t+d+.02);g.gain.exponentialRampToValueAtTime(.001,t+d+.5);o.connect(g);g.connect(_ac.destination);o.start(t+d);o.stop(t+d+.55)});
navigator.vibrate&&navigator.vibrate(urgent?[200,100,200,100,300]:[150])}catch(e){}}

function pushGo(t){if(!t||!me||!C.tabs)return;const ok=C.tabs.some(x=>x[0]==t)||Object.values(C.hubs||{}).some(h=>h.some(x=>x[0]==t));if(ok&&typeof V[t]=="function")go(t)}
if("serviceWorker" in navigator)navigator.serviceWorker.addEventListener("message",e=>{const m=e.data||{};
if(m.type=="push"){toast((m.title||"")+(m.body?" — "+m.body:""));ding(m.urgent);if(["home","appts","queue"].includes(tab)&&!C.chEdit)go(tab)}
else if(m.type=="goto")pushGo(m.tab)});
document.addEventListener("visibilitychange",()=>{if(document.visibilityState!="visible")return;try{navigator.clearAppBadge&&navigator.clearAppBadge();navigator.serviceWorker.ready.then(r=>r.getNotifications().then(l=>l.forEach(n=>n.close())))}catch(e){}});

// الاشتراك: ask=true بيطلب الإذن (لازم يتنادى من ضغطة زرار)، ask=false بيجدّد بصمت لو الإذن موجود
async function pushSync(ask){
if(!PUSH_OK()||typeof VAPID_PUBLIC_KEY=="undefined"||!VAPID_PUBLIC_KEY)return"unsupported";
if(Notification.permission=="denied")return"denied";
if(Notification.permission!="granted"){if(!ask)return"default";const p=await Notification.requestPermission();if(p!="granted")return p}
lsSet("push_off",null);
const reg=await navigator.serviceWorker.ready,key=b64u(VAPID_PUBLIC_KEY);let sub=await reg.pushManager.getSubscription();
if(sub){const cur=sub.options&&sub.options.applicationServerKey;if(cur){const a=new Uint8Array(cur);if(a.length!=key.length||a.some((v,i)=>v!=key[i])){await sub.unsubscribe();sub=null}}}
if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});
const j=sub.toJSON(),{error}=await sb.rpc("save_push_sub",{p_endpoint:j.endpoint,p_p256dh:j.keys.p256dh,p_auth:j.keys.auth,p_app:APP_MODE,p_ua:navigator.userAgent});
if(error)throw error;return"on"}
async function pushEnable(){try{const r=await pushSync(true);if(r=="on"){toast("تم تفعيل الإشعارات ✓");ding(false)}else if(r=="denied")toast("الإشعارات ممنوعة من إعدادات الموبايل أو المتصفح");else if(r=="unsupported")toast("الجهاز ده مش بيدعم الإشعارات");else toast("الإشعارات لسه مقفولة")}catch(e){toast("تعذر التفعيل: "+(e.message||e))}pushBellState();if($("sheet"))pushSheet()}
async function pushOff(){try{lsSet("push_off","1");const reg=await navigator.serviceWorker.ready,s=await reg.pushManager.getSubscription();if(s){await sb.rpc("remove_push_sub",{p_endpoint:s.endpoint});await s.unsubscribe()}toast("اتوقفت الإشعارات على الجهاز ده")}catch(e){toast(e.message||"تعذر الإيقاف")}pushBellState();pushSheet()}
async function pushUnlink(){try{if(!PUSH_OK())return;const reg=await navigator.serviceWorker.ready,s=await reg.pushManager.getSubscription();if(s)await sb.rpc("remove_push_sub",{p_endpoint:s.endpoint})}catch(e){}C.pb2=null;C.tabs=null;const b=$("pbell");b&&b.remove();const n=$("pbn");n&&n.remove()}
async function pushTest(){unlockAudio();toast("بنبعت إشعار تجربة...");const{data,error}=await sb.rpc("push_test");if(error)return toast(error.message);toast(data>0?"اتبعت لـ "+data+" جهاز. لو ما وصلش خلال ثواني راجع خطوات التفعيل":"مفيش جهاز مسجّل. فعّل الإشعارات الأول")}

async function pushStatus(){
if(typeof VAPID_PUBLIC_KEY=="undefined"||!VAPID_PUBLIC_KEY)return"nokey";
if(isIOS()&&!standalone())return"ios";
if(!PUSH_OK())return"unsup";
if(Notification.permission=="denied")return"denied";
if(Notification.permission!="granted")return"default";
try{const reg=await navigator.serviceWorker.ready;return(await reg.pushManager.getSubscription())?"on":"default"}catch(e){return"default"}}
const PMSG={nokey:"مفتاح الإشعارات (VAPID) ناقص في config.js.",ios:"على الآيفون لازم تثبّت التطبيق الأول: اضغط زر المشاركة ثم «إضافة إلى الشاشة الرئيسية»، وافتحه من الأيقونة، وبعدين فعّل الإشعارات من هنا.",unsup:"المتصفح ده مش بيدعم الإشعارات. جرّب Chrome، أو Safari على آيفون 16.4 أو أحدث.",denied:"الإشعارات ممنوعة لموقع الصالون. افتح إعدادات الموبايل أو المتصفح ← إعدادات الموقع ← الإشعارات وسمح بيها، وارجع هنا.",default:"الإشعارات مقفولة على الجهاز ده. فعّلها عشان توصلك حتى لو التطبيق مقفول.",on:"الإشعارات شغّالة على الجهاز ده ✓ هتوصلك حتى لو التطبيق مقفول."};
async function pushSheet(){const k=await pushStatus(),o=$("sheet");if(o)o.remove();const w=document.createElement("div");w.id="sheet";w.className="sheet-bg";w.onclick=e=>{if(e.target==w)svcClose()};
w.innerHTML=`<div class="sheet" role="dialog" aria-modal="true"><div class="sheet-h"><b>الإشعارات</b><button class="btn g s" onclick="svcClose()" aria-label="إغلاق">✕</button></div><p class="m" style="margin-top:0">${PMSG[k]}</p>${k=="default"?`<button class="btn" style="width:100%" onclick="pushEnable()">تفعيل الإشعارات</button>`:""}${k=="on"?`<button class="btn" style="width:100%" onclick="pushTest()">أبعت إشعار تجربة</button><button class="btn g" style="width:100%;margin-top:8px" onclick="pushOff()">إيقاف على الجهاز ده</button>`:""}<label class="row" style="cursor:pointer;margin-top:12px"><span>صوت التنبيه جوه التطبيق</span><input type="checkbox" ${pushSound()?"checked":""} onchange="pushSetSound(this.checked)" style="width:22px;height:22px;margin:0"></label><button class="btn g s" style="margin-top:8px" onclick="ding(true)">جرّب الصوت</button><p class="m">وهو التطبيق مقفول، صوت الإشعار بيطلع بصوت الموبايل الافتراضي للإشعارات، وتقدر تغيّره من إعدادات إشعارات الموبايل أو المتصفح.</p></div>`;document.body.appendChild(w)}
function pushBell(){if($("pbell"))return;const h=document.querySelector("header.top");if(!h)return;const b=document.createElement("button");b.id="pbell";b.className="bell";b.setAttribute("aria-label","الإشعارات");b.innerHTML=ic("bell");b.onclick=pushSheet;h.appendChild(b);pushBellState()}
async function pushBellState(){const b=$("pbell");if(!b)return;const on=(await pushStatus())=="on";if($("pbell"))$("pbell").className="bell"+(on?" on":"")}
function pushBanner(){if($("pbn")||!PUSH_OK()||typeof VAPID_PUBLIC_KEY=="undefined"||!VAPID_PUBLIC_KEY||Notification.permission!="default"||lsGet("push_x")||lsGet("push_off")||(isIOS()&&!standalone()))return;
const d=document.createElement("div");d.id="pbn";d.className="inst";d.innerHTML=`<span style="flex:1">فعّل الإشعارات عشان توصلك بصوت حتى لو التطبيق مقفول</span><button class="btn s" id="pbnb">تفعيل</button><button aria-label="إغلاق" id="pbnx" style="background:none;border:0;color:inherit;font-size:22px;cursor:pointer">×</button>`;document.body.appendChild(d);
$("pbnb").onclick=()=>{d.remove();pushEnable()};$("pbnx").onclick=()=>{d.remove();lsSet("push_x","1")}}
async function pushAfterBoot(){const{data:{session}}=await sb.auth.getSession();if(!session||!me||!C.tabs)return;pushBell();
const t=new URLSearchParams(location.search).get("tab");if(t){history.replaceState(null,"",location.pathname);pushGo(t)}
if(C.pb2==me.id)return;C.pb2=me.id;
if(PUSH_OK()&&Notification.permission=="granted"){if(!lsGet("push_off")){try{await pushSync(false)}catch(e){}}}else setTimeout(pushBanner,1800);
pushBellState()}
const _boot=boot;boot=async function(){const r=await _boot.apply(this,arguments);pushAfterBoot().catch(()=>{});return r};

// ================= تفاصيل الـ KPI + تفاصيل الفاتورة =================
// أي كارت رقم بيتضغط عليه بيفتح نافذة فيها الداتا اللي اتحسب منها الرقم، والفاتورة بتفتح بتفاصيلها كاملة.
// PAYL متعرّف فوق في ملف التقارير
const LYR={redeem:"استبدال",visit:"زيارة",purchase:"فاتورة",invoice:"فاتورة",review:"تقييم",welcome:"هدية تسجيل",admin:"تعديل إداري",adjust:"تعديل إداري",visit_bonus:"مكافأة زيارات"};
const dsT=d=>d?new Date(d).toLocaleString("ar-EG",{day:"numeric",month:"numeric",hour:"2-digit",minute:"2-digit"}):"—";
const dsPh=()=>!!me&&(me.role=="owner"||can("view_customer_phone"));
const dsRow=(a,b,c)=>`<div class="row"><div>${a}${b?`<div class="m">${b}</div>`:""}</div>${c?`<div style="text-align:left">${c}</div>`:""}</div>`;
const dsKv=(l,v,b)=>`<div style="display:flex;justify-content:space-between;gap:10px;padding:4px 0;${b?"font-weight:800;border-top:1px solid var(--line);margin-top:4px":""}"><span>${l}</span><span>${v}</span></div>`;
const dsEmpty=m=>`<p class="m">${m||"مفيش بيانات في الفترة دي."}</p>`;

function dsOpen(title,html,o){o=o||{};if(o.list)C.dsL={t:title,h:html};
  const old=$("sheet");if(old)old.remove();
  const w=document.createElement("div");w.id="sheet";w.className="sheet-bg";w.onclick=e=>{if(e.target==w)svcClose()};
  w.innerHTML=`<div class="sheet" role="dialog" aria-modal="true"><div class="sheet-h"><b>${esc(title)}</b><span>${o.back&&C.dsL?`<button class="btn g s" onclick="dsBack()">‹ رجوع</button> `:""}<button class="btn g s" onclick="svcClose()" aria-label="إغلاق">✕</button></span></div>${html}</div>`;
  document.body.appendChild(w)}
const dsLoad=t=>dsOpen(t,`<p class="m">بنحمّل...</p>`);
function dsBack(){const L=C.dsL;if(L)dsOpen(L.t,L.h,{list:1})}
async function dsQ(t,p,f){dsLoad(t);const{data,error}=await p;if(error)return dsOpen(t,dsEmpty(error.message));const L=data||[];dsOpen(t,L.length?f(L):dsEmpty(),{list:1})}

// ---- قايمة فواتير (بفلاتر) ← الضغط على فاتورة يفتح تفاصيلها ----
async function dsInv(o){dsLoad(o.t);
  let q=sb.from("invoices").select("id,no,total,discount,payment_method,created_at,customers(name),barber:barber_id(full_name),invoice_items(name,qty)").order("created_at",{ascending:false}).limit(200);
  if(o.from)q=q.gte("created_at",o.from);if(o.to)q=q.lt("created_at",o.to);
  if(o.barber)q=q.eq("barber_id",o.barber);if(o.customer)q=q.eq("customer_id",o.customer);
  if(o.pay)q=q.eq("payment_method",o.pay);if(o.disc)q=q.gt("discount",0);
  const{data,error}=await q;if(error)return dsOpen(o.t,dsEmpty(error.message));
  const L=data||[];
  const h=L.length?`<div class="m" style="margin-bottom:8px">${L.length>=200?"أحدث 200 فاتورة":L.length+" فاتورة"} · ${L.length>=200?"إجمالي المعروض":"الإجمالي"} <b>${fm(sumOf(L,x=>x.total))}</b>${o.disc?" · خصومات "+fm(sumOf(L,x=>x.discount)):""}</div>`+L.map(i=>`<button class="row" style="cursor:pointer;width:100%;text-align:right" onclick="dsInvOne(${i.id})"><div><b>#${i.no}</b> · ${esc(i.customers?.name||"عميل عابر")}<div class="m">${dsT(i.created_at)} · ${(i.invoice_items||[]).map(z=>esc(z.name)+(z.qty>1?" ×"+z.qty:"")).join(" + ")}</div><div class="m">الحلاق: ${esc(i.barber?.full_name||"—")}</div></div><div style="text-align:left"><b>${fm(i.total)}</b><div class="m">${PAYL[i.payment_method]||esc(i.payment_method)}${+i.discount>0?" · خصم "+fm(i.discount):""}</div></div></button>`).join(""):dsEmpty("مفيش فواتير في الفترة دي.");
  dsOpen(o.t,h,{list:1})}

// ---- تفاصيل فاتورة واحدة: الزبون / مين اشتغل / اتعمل إيه / الحساب ----
async function dsInvOne(id){dsLoad("تفاصيل الفاتورة");
  const{data:i,error}=await sb.from("invoices").select("id,no,subtotal,discount,total,payment_method,created_at,customers(name,phone,visits),barber:barber_id(full_name),cashier:cashier_id(full_name),invoice_items(id,name,qty,unit_price,item_type,assistant_cut,assistant:assistant_id(full_name))").eq("id",id).maybeSingle();
  if(error||!i)return dsOpen("تفاصيل الفاتورة",dsEmpty(error?error.message:"الفاتورة مش موجودة."),{back:1});
  const it=i.invoice_items||[],asst=[...new Set(it.map(x=>x.assistant?.full_name).filter(Boolean))],cu=i.customers;
  dsOpen("فاتورة #"+i.no,`<div class="m" style="margin-bottom:8px">${new Date(i.created_at).toLocaleString("ar-EG",{weekday:"long",day:"numeric",month:"long",year:"numeric",hour:"2-digit",minute:"2-digit"})}</div>
<h2>الزبون</h2><div class="box">${cu?dsKv("الاسم",`<b>${esc(cu.name)}</b>`)+(dsPh()&&cu.phone?dsKv("الموبايل",`<span dir="ltr">${esc(cu.phone)}</span>`):"")+(cu.visits!=null?dsKv("عدد زياراته",cu.visits):""):`<span class="m">عميل عابر (من غير حساب)</span>`}</div>
<h2>مين اشتغل</h2><div class="box">${dsKv("الحلاق",`<b>${esc(i.barber?.full_name||"—")}</b>`)}${asst.length?dsKv("المساعد",asst.map(a=>esc(a)).join("، ")):""}${dsKv("الكاشير (اللي حاسب)",esc(i.cashier?.full_name||"—"))}</div>
<h2>اتعمل إيه</h2><div class="box">${it.map(x=>`<div style="padding:5px 0;border-bottom:1px dashed var(--line)"><div style="display:flex;justify-content:space-between;gap:10px"><span><b>${esc(x.name)}</b> <span class="tag">${x.item_type=="product"?"منتج":"خدمة"}</span></span><b>${fm(x.unit_price*x.qty)}</b></div><div class="m">${x.qty>1?x.qty+" × "+fm(x.unit_price):"سعر "+fm(x.unit_price)}${x.assistant?` · المساعد: ${esc(x.assistant.full_name)}${+x.assistant_cut?` (اتخصم ${fm(x.assistant_cut)} للمساعد)`:""}`:""}</div></div>`).join("")||`<span class="m">مفيش بنود</span>`}</div>
<h2>الحساب</h2><div class="box">${dsKv("المجموع",fm(i.subtotal))}${+i.discount>0?dsKv("الخصم","- "+fm(i.discount)):""}${dsKv("الإجمالي",fm(i.total),1)}${dsKv("طريقة الدفع",PAYL[i.payment_method]||esc(i.payment_method))}</div>
${me.role=="owner"?`<button class="btn s g" style="color:var(--red);margin-top:8px" onclick="svcClose();delInv('${i.id}')">حذف الفاتورة</button>`:""}`,{back:1})}

// ---- الرئيسية: كروت الدور والإيراد ----
function dsToday(){const[a,b]=rangeR("today");dsInv({t:"فواتير النهارده",from:a.toISOString(),to:b.toISOString()})}
function dsAppts(ks,t){const A=(C.A||[]).filter(a=>!ks||ks.includes(a.status));
  dsOpen(t,A.length?A.map(a=>dsRow(`<b>#${a.ticket_no} · ${esc(a.customers?.name||"عميل")}</b>`,`${(a.appointment_services||[]).map(x=>esc(x.services?.name||"")).filter(Boolean).join(" + ")||"—"}${a.profiles?.full_name?" · الحلاق: "+esc(a.profiles.full_name):""}`,`<span class="tag">${ST[a.status]||a.status}</span>`)).join(""):dsEmpty("مفيش حاجة هنا دلوقتي."))}

// ---- الخزنة: كروت الفترة + اليوم ----
function dsBar(id,pay){const P=C.kp;if(!P)return;const b=id&&(P.bars||[]).find(x=>x.id==id);dsInv({t:b?"فواتير "+b.n:"فواتير "+PAYL[pay]+" في الفترة",from:P.A,to:P.B,barber:id||null,pay:pay||null})}
function dsAll(){const P=C.kp;if(P)dsInv({t:"كل فواتير الفترة",from:P.A,to:P.B})}
function dsDayPay(p){const day=C.cd||ymd(new Date()),a=new Date(day+"T00:00"),b=new Date(a);b.setDate(b.getDate()+1);dsInv({t:"فواتير "+PAYL[p]+" — "+day,from:a.toISOString(),to:b.toISOString(),pay:p})}

// ---- التقارير ----
const rpR=()=>({from:C.rr[0].toISOString(),to:C.rr[1].toISOString()});
const dsCuRow=c=>{(C.dsN=C.dsN||{})[c.id]=c.name;return `<button class="row" style="cursor:pointer;width:100%;text-align:right" onclick="dsCust(${c.id})"><div><b>${esc(c.name)}</b><div class="m">${dsPh()&&c.phone?`<span dir="ltr">${esc(c.phone)}</span> · `:""}${c.sub||""}</div></div>${c.end?`<div style="text-align:left">${c.end}</div>`:""}</button>`};
function dsCust(id){const n=(C.dsN||{})[id]||((C.CU||[]).find(y=>y.id==id)||{}).name||"العميل";dsInv({t:"فواتير "+n,customer:id})}
function dsLoyC(id){const n=(C.dsN||{})[id]||((C.CU||[]).find(y=>y.id==id)||{}).name||"العميل";
  dsQ("نقاط "+n,sb.from("loyalty_ledger").select("points,reason,note,created_at").eq("customer_id",id).order("created_at",{ascending:false}).limit(200),L=>L.map(x=>dsRow(`<b>${esc(LYR[x.reason]||x.reason)}</b>`,dsT(x.created_at)+(x.note?" · "+esc(x.note):""),`<b style="color:${x.points>0?"var(--ok)":"var(--red)"}">${x.points>0?"+":""}${x.points}</b>`)).join(""))}
async function rp(k){const R=rpR(),T=(C.rd||{}).totals||{};
  if(k=="inv")return dsInv({t:"فواتير الفترة",...R});
  if(k=="disc")return dsInv({t:"الفواتير اللي عليها خصم",...R,disc:true});
  if(PAYL[k])return dsInv({t:"فواتير "+PAYL[k],...R,pay:k});
  if(k=="profit"){const L=[["المبيعات",T.revenue,1],["تكلفة المنتجات المباعة",-T.cogs],["عمولات الحلاقين (بعد خصم المساعدين)",-T.commissions],["رواتب المساعدين",-(T.salaries||0)],["المكافآت",-T.bonuses],["الخصومات على الموظفين",T.deductions],["المصروفات",-T.expenses],["صافي الربح",T.profit,1]];
    return dsOpen("إزاي طلع صافي الربح",`<div class="box">${L.map(r=>dsKv(r[0],fm(r[1]||0),r[2])).join("")}</div>`)}
  if(k=="exp"){const X=C.rx||[];return dsOpen("مصروفات الفترة",X.length?`<div class="m" style="margin-bottom:8px">${X.length} بند · <b>${fm(sumOf(X,x=>x.amount))}</b></div>`+X.map(x=>dsRow(`<b>${esc(x.category)}</b>`,`${x.spent_on}${x.note?" · "+esc(x.note):""}`,`<b>${fm(x.amount)}</b>`)).join(""):dsEmpty("مفيش مصروفات في الفترة دي."))}
  if(k=="bonus"||k=="advance"||k=="deduction")return dsQ({bonus:"المكافآت",advance:"السحب (السلف)",deduction:"الخصومات"}[k]+" في الفترة",sb.from("staff_transactions").select("amount,note,created_at,profiles(full_name)").eq("kind",k).gte("created_at",R.from).lt("created_at",R.to).order("created_at",{ascending:false}),L=>`<div class="m" style="margin-bottom:8px">${L.length} حركة · <b>${fm(sumOf(L,x=>x.amount))}</b></div>`+L.map(x=>dsRow(`<b>${esc(x.profiles?.full_name||"—")}</b>`,dsT(x.created_at)+(x.note?" · "+esc(x.note):""),`<b>${fm(x.amount)}</b>`)).join(""));
  if(k=="cu_all"||k=="cu_new"){let q=sb.from("customers").select("id,name,phone,visits,points,created_at").order("created_at",{ascending:false}).limit(300);if(k=="cu_new")q=q.gte("created_at",R.from).lt("created_at",R.to);
    return dsQ(k=="cu_new"?"العملاء الجدد":"كل العملاء",q,L=>L.map(c=>dsCuRow({...c,sub:c.visits+" زيارة · "+dsT(c.created_at),end:`<span class="tag">${c.points} نقطة</span>`})).join(""))}
  if(k=="cu_act")return dsQ("العملاء النشطين في الفترة",sb.from("invoices").select("customer_id,total,customers(name,phone)").gte("created_at",R.from).lt("created_at",R.to).not("customer_id","is",null).limit(2000),L=>{const g={};L.forEach(x=>{const o=g[x.customer_id]=g[x.customer_id]||{id:x.customer_id,name:x.customers?.name||"—",phone:x.customers?.phone,n:0,t:0};o.n++;o.t+=+x.total});
    return Object.values(g).sort((a,b)=>b.t-a.t).map(c=>dsCuRow({...c,sub:c.n+" فاتورة",end:`<b>${fm(c.t)}</b>`})).join("")});
  if(k=="ly_in"||k=="ly_out"){let q=sb.from("loyalty_ledger").select("points,reason,note,created_at,customers(name)").gte("created_at",R.from).lt("created_at",R.to).order("created_at",{ascending:false}).limit(300);q=k=="ly_in"?q.gt("points",0):q.eq("reason","redeem");
    return dsQ(k=="ly_in"?"النقاط الممنوحة":"النقاط المستبدلة",q,L=>L.map(x=>dsRow(`<b>${esc(x.customers?.name||"—")}</b>`,dsT(x.created_at)+" · "+esc(LYR[x.reason]||x.reason)+(x.note?" · "+esc(x.note):""),`<b style="color:${x.points>0?"var(--ok)":"var(--red)"}">${x.points>0?"+":""}${x.points}</b>`)).join(""))}
  if(k=="cp_a"||k=="cp_u"){let q=sb.from("loyalty_redemptions").select("code,status,created_at,used_at,loyalty_rewards(name),customers(name)").order("created_at",{ascending:false}).limit(200);q=k=="cp_a"?q.eq("status","active"):q.eq("status","used").gte("used_at",R.from).lt("used_at",R.to);
    return dsQ(k=="cp_a"?"الكوبونات المفعّلة":"الكوبونات اللي اتستخدمت",q,L=>L.map(x=>dsRow(`<b>${esc(x.loyalty_rewards?.name||"—")}</b> · ${esc(x.customers?.name||"—")}`,`كود ${esc(x.code)} · ${dsT(x.used_at||x.created_at)}`,`<span class="tag">${x.status=="used"?"اتستخدم":"مفعّل"}</span>`)).join(""))}
  if(k=="ap_all"||k=="ap_can"){let q=sb.from("appointments").select("ticket_no,status,day,period,customers(name),profiles(full_name),appointment_services(services(name))").gte("created_at",R.from).lt("created_at",R.to).order("created_at",{ascending:false}).limit(300);if(k=="ap_can")q=q.eq("status","cancelled");
    return dsQ(k=="ap_can"?"الحجوزات الملغية":"حجوزات الفترة",q,L=>L.map(x=>dsRow(`<b>#${x.ticket_no??"-"} · ${esc(x.customers?.name||"—")}</b>`,`${x.day||""}${x.period?" · "+(PLB[x.period]||""):""} · ${(x.appointment_services||[]).map(s=>esc(s.services?.name||"")).filter(Boolean).join(" + ")||"—"}${x.profiles?.full_name?" · الحلاق: "+esc(x.profiles.full_name):""}`,`<span class="tag">${ST[x.status]||x.status}</span>`)).join(""))}
  if(k=="rev")return dsQ("تقييمات الفترة",sb.from("reviews").select("rating,service_rating,place_rating,tags,note,created_at,customers(name),profiles:barber_id(full_name)").gte("created_at",R.from).lt("created_at",R.to).order("created_at",{ascending:false}).limit(200),L=>L.map(x=>`<div class="row" style="display:block"><b style="color:var(--brass)">${"★".repeat(x.rating)}</b> <b>${esc(x.customers?.name||"—")}</b><div class="m">الحلاق: ${esc(x.profiles?.full_name||"—")} · ${dsT(x.created_at)}${x.service_rating?" · الخدمة ★"+x.service_rating:""}${x.place_rating?" · المكان ★"+x.place_rating:""}${(x.tags||[]).length?" · "+x.tags.map(esc).join("، "):""}</div>${x.note?`<div>${esc(x.note)}</div>`:""}</div>`).join(""));
  if(k=="stock")return dsQ("المخزون",sb.from("products").select("name,stock,min_stock,cost,price,active").order("name"),L=>L.map(p=>dsRow(`<b>${esc(p.name)}</b>${p.active?"":" (موقوف)"}`,`تكلفة ${fm(p.cost)} · بيع ${fm(p.price)} · قيمته ${fm(p.cost*p.stock)}`,`<span class="tag" style="${p.stock<=p.min_stock?"background:var(--red);color:#fff":""}">${p.stock} قطعة</span>`)).join(""))}

// ---- شاشة الموظف (مبيعاتي / عمولتي / سحب ...) ----
function pnInv(){const P=C.pn;if(!P)return;if(!(me.role=="owner"||can("view_invoices")))return toast("عرض الفواتير مش متاح لحسابك");dsInv({t:P.owner?"فواتير الحلاق في الفترة":"فواتيري في الفترة",from:P.f,to:P.t,barber:P.id})}
function pnTx(k){const P=C.pn;if(!P)return;const L=(P.tx||[]).filter(x=>x.kind==k);dsOpen({bonus:"المكافآت",advance:"السحب",deduction:"الخصومات"}[k]+" في الفترة",L.length?`<div class="m" style="margin-bottom:8px">${L.length} حركة · <b>${fm(sumOf(L,x=>x.amount))}</b></div>`+L.map(x=>dsRow(`<b>${fm(x.amount)}</b>`,dsT(x.created_at)+(x.note?" · "+esc(x.note):""))).join(""):dsEmpty())}
function pnAl(){const P=C.pn;if(!P)return;const as=P.s.who=="assistant",L=P.al||[];dsOpen(as?"الخدمات اللي شاركت فيها":"خصم المساعدين على خدماتك",L.length?L.map(x=>dsRow(`<b>#${x.inv_no}</b> · ${esc(x.service_name)} · ${fm(x.price)}`,new Date(x.created).toLocaleDateString("ar-EG")+" · "+(as?"مع الحلاق "+esc(x.barber_name||"—"):"اتخصم للمساعد "+esc(x.assistant_name)),as?"":`<b style="color:var(--red)">- ${fm(x.cut)}</b>`)).join(""):dsEmpty())}
function pnNet(){const P=C.pn;if(!P)return;const s=P.s,L=[["العمولة",+s.commission||0],["راتب ثابت",+s.salary||0],["مكافآت",+s.bonuses||0],["سحب",-(+s.advances||0)],["خصومات",-(+s.deductions||0)]].filter(r=>r[1]);
  dsOpen("إزاي طلع الصافي",`<div class="box">${L.map(r=>dsKv(r[0],fm(r[1]))).join("")}${dsKv("الصافي المستحق",fm(+s.net||0),1)}</div><div class="m" style="margin-top:6px">العمولة محسوبة بعد خصم نسبة المساعدين.</div>`)}


boot();
